public class OverdueInvoiceBatch implements Database.Batchable<SObject>, Database.Stateful {
    private Integer recordsUpdated;
    private Integer recordsFailed;
    private Decimal overdueAmount;

    public OverdueInvoiceBatch() {
        this.recordsUpdated = 0;
        this.recordsFailed = 0;
        this.overdueAmount = 0;
    }

    public Database.QueryLocator start(Database.BatchableContext bc) {
        return Database.getQueryLocator([
            SELECT Id, Status__c, Due_Date__c, Amount__c, Customer_Email__c
            FROM FB_Invoice__c
            WHERE Status__c = 'Open'
            AND Due_Date__c < TODAY
        ]);
    }

    public void execute(Database.BatchableContext bc, List<SObject> scope) {
        if (scope == null || scope.isEmpty()) {
            return;
        }

        List<FB_Invoice__c> invoices = new List<FB_Invoice__c>();
        for (SObject record : scope) {
            FB_Invoice__c invoice = (FB_Invoice__c) record;
            invoice.Status__c = 'Overdue';
            invoices.add(invoice);
        }

        List<Database.SaveResult> results = Database.update(invoices, false);

        for (Integer i = 0; i < results.size(); i++) {
            Database.SaveResult result = results[i];
            if (result.isSuccess()) {
                recordsUpdated++;
                Decimal amount = invoices[i].Amount__c;
                overdueAmount += (amount == null ? 0 : amount);
            } else {
                recordsFailed++;
            }
        }
    }

    public void finish(Database.BatchableContext bc) {
        insert new FB_Job_Summary__c(
            Job_Name__c = 'OverdueInvoiceBatch',
            Records_Updated__c = recordsUpdated,
            Records_Failed__c = recordsFailed,
            Overdue_Amount__c = overdueAmount
        );
    }
}
