public with sharing class ExchangeRateClient {

    public class ExchangeRateException extends Exception {}

    private static final String ENDPOINT = 'callout:FB_Exchange_Rates/v1/latest';

    public static Map<String, Decimal> getRates(String baseCurrency, Set<String> quoteCurrencies) {
        // Validation and normalisation - before any callout
        String normalizedBase = normalizeAndValidate(baseCurrency);

        if (quoteCurrencies == null || quoteCurrencies.isEmpty()) {
            throw new ExchangeRateException('Quote currencies must not be null or empty.');
        }

        Set<String> normalizedQuotes = new Set<String>();
        for (String quoteCurrency : quoteCurrencies) {
            normalizedQuotes.add(normalizeAndValidate(quoteCurrency));
        }

        if (normalizedQuotes.isEmpty()) {
            throw new ExchangeRateException('Quote currencies must not be null or empty.');
        }

        List<String> sortedQuotes = new List<String>(normalizedQuotes);
        sortedQuotes.sort();

        String endpoint = ENDPOINT
            + '?base=' + EncodingUtil.urlEncode(normalizedBase, 'UTF-8')
            + '&symbols=' + String.join(sortedQuotes, ',');

        HttpRequest request = new HttpRequest();
        request.setEndpoint(endpoint);
        request.setMethod('GET');
        request.setHeader('Accept', 'application/json');

        Http http = new Http();
        HttpResponse response;

        // One request, with a single identical retry on 503
        for (Integer attempt = 0; attempt < 2; attempt++) {
            response = http.send(request);
            Integer statusCode = response.getStatusCode();

            if (statusCode == 503 && attempt == 0) {
                continue;
            }

            if (statusCode != 200) {
                throw new ExchangeRateException(
                    'Exchange rate request failed with status code ' + statusCode + '.'
                );
            }

            break;
        }

        // Parse 200 response
        String body = response.getBody();
        if (body == null) {
            throw new ExchangeRateException('Exchange rate response body could not be parsed.');
        }

        Object parsed;
        try {
            parsed = JSON.deserializeUntyped(body);
        } catch (Exception e) {
            throw new ExchangeRateException(
                'Exchange rate response body could not be parsed: ' + e.getMessage()
            );
        }

        if (!(parsed instanceof Map<String, Object>)) {
            throw new ExchangeRateException('Exchange rate response body could not be parsed.');
        }

        Map<String, Object> root = (Map<String, Object>) parsed;
        Object ratesObj = root.get('rates');

        if (!(ratesObj instanceof Map<String, Object>)) {
            throw new ExchangeRateException('Exchange rate response body could not be parsed.');
        }

        Map<String, Object> rates = (Map<String, Object>) ratesObj;

        Map<String, Decimal> result = new Map<String, Decimal>();
        for (String quote : sortedQuotes) {
            Object rateValue = rates.get(quote);
            if (rateValue == null) {
                throw new ExchangeRateException(
                    'Missing exchange rate for currency: ' + quote
                );
            }

            Decimal rate;
            try {
                if (rateValue instanceof Decimal) {
                    rate = (Decimal) rateValue;
                } else if (rateValue instanceof Double) {
                    rate = Decimal.valueOf((Double) rateValue);
                } else if (rateValue instanceof Integer) {
                    rate = Decimal.valueOf((Integer) rateValue);
                } else if (rateValue instanceof Long) {
                    rate = Decimal.valueOf((Long) rateValue);
                } else {
                    rate = Decimal.valueOf(String.valueOf(rateValue));
                }
            } catch (Exception e) {
                throw new ExchangeRateException(
                    'Exchange rate response body could not be parsed: ' + e.getMessage()
                );
            }

            result.put(quote, rate);
        }

        return result;
    }

    private static String normalizeAndValidate(String code) {
        if (code == null) {
            throw new ExchangeRateException('Invalid currency code: ' + code);
        }

        String normalized = code.trim().toUpperCase();

        if (!Pattern.compile('^[A-Z]{3}$').matcher(normalized).matches()) {
            throw new ExchangeRateException('Invalid currency code: ' + code);
        }

        return normalized;
    }
}
