/**
 * Service for grouping Contacts by their email domain.
 */
public with sharing class ContactDomainService {

    /**
     * Returns the Contacts of the given Accounts grouped by the domain
     * part of their email address, lower-cased.
     *
     * Contacts without an email, or without a parsable domain, are excluded.
     * A null or empty set of Account Ids returns an empty map.
     *
     * Sharing is respected by virtue of the class being declared
     * `with sharing` and querying Contact directly, so only Contacts
     * visible to the running user are returned.
     *
     * @param accountIds Ids of the Accounts whose Contacts should be grouped.
     * @return Map from lower-cased email domain to the Contacts in that domain.
     */
    public static Map<String, List<Contact>> groupByEmailDomain(Set<Id> accountIds) {
        Map<String, List<Contact>> contactsByDomain = new Map<String, List<Contact>>();

        if (accountIds == null || accountIds.isEmpty()) {
            return contactsByDomain;
        }

        Set<Id> validAccountIds = new Set<Id>();
        for (Id accountId : accountIds) {
            if (accountId != null) {
                validAccountIds.add(accountId);
            }
        }
        if (validAccountIds.isEmpty()) {
            return contactsByDomain;
        }

        for (Contact contactRecord : [
            SELECT Id, Email, AccountId
            FROM Contact
            WHERE AccountId IN :validAccountIds
            AND Email != null
        ]) {
            String email = contactRecord.Email == null
                ? null
                : contactRecord.Email.trim();
            if (String.isBlank(email)) {
                continue;
            }

            Integer atIndex = email.lastIndexOf('@');
            if (atIndex < 0 || atIndex == email.length() - 1) {
                continue;
            }

            String domain = email.substring(atIndex + 1).trim().toLowerCase();
            if (String.isBlank(domain)) {
                continue;
            }

            List<Contact> contactsInDomain = contactsByDomain.get(domain);
            if (contactsInDomain == null) {
                contactsInDomain = new List<Contact>();
                contactsByDomain.put(domain, contactsInDomain);
            }
            contactsInDomain.add(contactRecord);
        }

        return contactsByDomain;
    }
}
