public class PaymentTerms {
    private static final Pattern NET_PATTERN = Pattern.compile('(?i)^NET\\s*(\\d{1,3})$');
    private static final Pattern DUE_ON_RECEIPT_PATTERN = Pattern.compile('(?i)^DUE\\s+ON\\s+RECEIPT$');
    private static final Integer MAX_NET_DAYS = 180;

    public static Integer parseNetDays(String terms) {
        if (terms == null) {
            throw new UnsupportedTermsException('Unsupported payment terms: null');
        }

        String trimmedTerms = terms.trim();

        if (String.isBlank(trimmedTerms)) {
            throw new UnsupportedTermsException('Unsupported payment terms: ' + terms);
        }

        if (DUE_ON_RECEIPT_PATTERN.matcher(trimmedTerms).matches()) {
            return 0;
        }

        Matcher netMatcher = NET_PATTERN.matcher(trimmedTerms);
        if (netMatcher.matches()) {
            Integer netDays = Integer.valueOf(netMatcher.group(1));
            if (netDays > MAX_NET_DAYS) {
                throw new TermsOutOfRangeException('Net days out of range: ' + netDays);
            }
            return netDays;
        }

        throw new UnsupportedTermsException('Unsupported payment terms: ' + terms);
    }

    public static Date dueDate(Date invoiceDate, String terms) {
        Integer netDays = parseNetDays(terms);
        return invoiceDate.addDays(netDays);
    }
}
