public with sharing class RecordSearchService {

    public class SearchException extends Exception {
    }

    public static List<SObject> search(
        String objectApiName,
        List<String> fields,
        Map<String, Object> filters,
        String orderByField,
        Integer maxRows
    ) {
        try {
            return doSearch(objectApiName, fields, filters, orderByField, maxRows);
        } catch (SearchException e) {
            throw e;
        } catch (Exception e) {
            String msg = e.getMessage();
            throw new SearchException(String.isBlank(msg) ? 'Search failed.' : msg);
        }
    }

    private static List<SObject> doSearch(
        String objectApiName,
        List<String> fields,
        Map<String, Object> filters,
        String orderByField,
        Integer maxRows
    ) {
        // maxRows validation
        if (maxRows == null || maxRows < 1 || maxRows > 200) {
            throw new SearchException('maxRows must be between 1 and 200.');
        }

        // fields presence validation
        if (fields == null || fields.isEmpty()) {
            throw new SearchException('fields must not be null or empty.');
        }

        // Object validation (case-insensitive)
        if (String.isBlank(objectApiName)) {
            throw new SearchException('Object does not exist: ' + objectApiName);
        }

        Schema.SObjectType sObjectType = null;
        String trimmedObjectName = objectApiName.trim();
        Map<String, Schema.SObjectType> globalDescribe = Schema.getGlobalDescribe();
        // Global describe keys are case-insensitive in practice (lowercase),
        // but handle any casing robustly.
        if (globalDescribe.containsKey(trimmedObjectName)) {
            sObjectType = globalDescribe.get(trimmedObjectName);
        } else if (globalDescribe.containsKey(trimmedObjectName.toLowerCase())) {
            sObjectType = globalDescribe.get(trimmedObjectName.toLowerCase());
        } else {
            for (String key : globalDescribe.keySet()) {
                if (key != null && key.equalsIgnoreCase(trimmedObjectName)) {
                    sObjectType = globalDescribe.get(key);
                    break;
                }
            }
        }

        if (sObjectType == null) {
            throw new SearchException('Object does not exist: ' + objectApiName);
        }

        Schema.DescribeSObjectResult objectDescribe = sObjectType.getDescribe();

        if (!objectDescribe.isQueryable()) {
            throw new SearchException('Object does not exist or is not queryable: ' + objectApiName);
        }

        // Object-level read access
        if (!objectDescribe.isAccessible()) {
            throw new SearchException('User cannot read object: ' + objectDescribe.getName());
        }

        // Field describe map by lower-case API name
        Map<String, Schema.DescribeFieldResult> fieldByLowerName =
            new Map<String, Schema.DescribeFieldResult>();
        for (Schema.SObjectField sField : objectDescribe.fields.getMap().values()) {
            Schema.DescribeFieldResult fd = sField.getDescribe();
            fieldByLowerName.put(fd.getName().toLowerCase(), fd);
        }

        // Resolve and validate requested fields
        List<String> selectFieldNames = new List<String>();
        Set<String> seenLower = new Set<String>();
        // Id is always selected first; avoid duplicating it if requested
        seenLower.add('id');
        selectFieldNames.add('Id');

        Schema.DescribeFieldResult idField = fieldByLowerName.get('id');
        if (idField == null) {
            throw new SearchException('Object does not have an Id field: ' + objectDescribe.getName());
        }
        if (!idField.isAccessible()) {
            throw new SearchException('User cannot read field: ' + idField.getName());
        }

        for (String fieldName : fields) {
            if (String.isBlank(fieldName)) {
                throw new SearchException('Field does not exist: ' + fieldName);
            }
            String key = fieldName.trim().toLowerCase();
            Schema.DescribeFieldResult fd = fieldByLowerName.get(key);
            if (fd == null) {
                throw new SearchException('Field does not exist: ' + fieldName);
            }
            if (!fd.isAccessible()) {
                throw new SearchException('User cannot read field: ' + fd.getName());
            }
            if (seenLower.contains(key)) {
                continue;
            }
            seenLower.add(key);
            selectFieldNames.add(fd.getName());
        }

        // Resolve and validate filters
        Map<String, Object> binds = new Map<String, Object>();
        List<String> whereClauses = new List<String>();

        if (filters != null && !filters.isEmpty()) {
            Integer bindIndex = 0;
            for (String filterFieldName : filters.keySet()) {
                if (String.isBlank(filterFieldName)) {
                    throw new SearchException('Field does not exist: ' + filterFieldName);
                }
                String key = filterFieldName.trim().toLowerCase();
                Schema.DescribeFieldResult fd = fieldByLowerName.get(key);
                if (fd == null) {
                    throw new SearchException('Field does not exist: ' + filterFieldName);
                }
                if (!fd.isAccessible()) {
                    throw new SearchException('User cannot read field: ' + fd.getName());
                }
                if (!fd.isFilterable()) {
                    throw new SearchException('Field cannot be filtered: ' + fd.getName());
                }
                String bindName = 'b' + bindIndex;
                bindIndex++;
                binds.put(bindName, filters.get(filterFieldName));
                // Only validated canonical field name is interpolated;
                // the value is supplied exclusively via a bind variable.
                whereClauses.add(fd.getName() + ' = :' + bindName);
            }
        }

        // Resolve and validate order-by field
        String orderByClause = '';
        if (!String.isBlank(orderByField)) {
            String key = orderByField.trim().toLowerCase();
            Schema.DescribeFieldResult fd = fieldByLowerName.get(key);
            if (fd == null) {
                throw new SearchException('Field does not exist: ' + orderByField);
            }
            if (!fd.isAccessible()) {
                throw new SearchException('User cannot read field: ' + fd.getName());
            }
            if (!fd.isSortable()) {
                throw new SearchException('Field cannot be sorted: ' + fd.getName());
            }
            orderByClause = ' ORDER BY ' + fd.getName() + ' ASC';
        }

        // Build the single SOQL query. Only validated canonical object/field
        // names and the validated integer limit are interpolated; all filter
        // values are bind variables, preventing SOQL injection.
        String query = 'SELECT ' + String.join(selectFieldNames, ', ')
            + ' FROM ' + objectDescribe.getName();

        if (!whereClauses.isEmpty()) {
            query += ' WHERE ' + String.join(whereClauses, ' AND ');
        }

        query += orderByClause;
        query += ' LIMIT ' + maxRows;

        List<SObject> results;
        try {
            // USER_MODE enforces object- and field-level security;
            // 'with sharing' on the class enforces record sharing.
            results = Database.queryWithBinds(query, binds, AccessLevel.USER_MODE);
        } catch (SearchException e) {
            throw e;
        } catch (Exception e) {
            String msg = e.getMessage();
            throw new SearchException(String.isBlank(msg) ? 'Search failed.' : msg);
        }

        return results == null ? new List<SObject>() : results;
    }
}
