public with sharing class ContactLookupAction {

    public class Request {
        @InvocableVariable(required=true label='Email')
        public String email;
    }

    public class Result {
        @InvocableVariable(label='Contact Id')
        public Id contactId;

        @InvocableVariable(label='Found')
        public Boolean found;

        public Result() {
            this.found = false;
            this.contactId = null;
        }
    }

    @InvocableMethod(label='Find Contact by Email' description='Finds an existing Contact by email address, matching case-insensitively.')
    public static List<Result> find(List<Request> requests) {
        List<Result> results = new List<Result>();

        if (requests == null || requests.isEmpty()) {
            return results;
        }

        List<String> normalizedEmails = new List<String>(requests.size());
        Set<String> emailsToQuery = new Set<String>();

        for (Request req : requests) {
            String normalized = null;
            if (req != null && !String.isBlank(req.email)) {
                normalized = req.email.trim().toLowerCase();
                if (String.isBlank(normalized)) {
                    normalized = null;
                } else {
                    emailsToQuery.add(normalized);
                }
            }
            normalizedEmails.add(normalized);
            results.add(new Result());
        }

        if (!emailsToQuery.isEmpty()) {
            Map<String, Id> earliestContactIdByEmail = new Map<String, Id>();

            // Single bulkified query. 'with sharing' on the class enforces
            // the running user's sharing rules. SOQL string matching is
            // case-insensitive, and results are additionally keyed by
            // lower-cased email below. Earliest CreatedDate wins because
            // of the ordering and first-wins population of the map.
            for (Contact con : [
                SELECT Id, Email
                FROM Contact
                WHERE Email IN :emailsToQuery
                ORDER BY CreatedDate ASC, Id ASC
            ]) {
                if (String.isBlank(con.Email)) {
                    continue;
                }
                String key = con.Email.trim().toLowerCase();
                if (!earliestContactIdByEmail.containsKey(key)) {
                    earliestContactIdByEmail.put(key, con.Id);
                }
            }

            for (Integer i = 0; i < requests.size(); i++) {
                String normalized = normalizedEmails[i];
                if (normalized != null && earliestContactIdByEmail.containsKey(normalized)) {
                    results[i].contactId = earliestContactIdByEmail.get(normalized);
                    results[i].found = true;
                } else {
                    results[i].contactId = null;
                    results[i].found = false;
                }
            }
        }

        return results;
    }
}
