public class OrderPayloadParser {

    public class PayloadException extends Exception {
    }

    public class Order {
        public String orderNumber;
        public Date orderDate;
        public String currencyCode;
        public String customerEmail;
        public List<Line> lines;
        public Decimal total;
    }

    public class Line {
        public String sku;
        public Integer quantity;
        public Decimal unitPrice;
        public Decimal discount;
        public Decimal lineTotal;
    }

    public static Order parse(String body) {
        try {
            if (String.isBlank(body)) {
                throw new PayloadException('Request body is null or blank.');
            }

            Object parsed;
            try {
                parsed = JSON.deserializeUntyped(body);
            } catch (Exception e) {
                throw new PayloadException('Body is not valid JSON: ' + e.getMessage());
            }

            if (!(parsed instanceof Map<String, Object>)) {
                throw new PayloadException('Body must be a JSON object.');
            }
            Map<String, Object> root = (Map<String, Object>) parsed;

            String orderNumber = getStringValue(root.get('number'), 'number');
            if (String.isBlank(orderNumber)) {
                throw new PayloadException('Missing or blank number.');
            }

            Order result = new Order();
            result.orderNumber = orderNumber;
            result.currencyCode = getStringValue(root.get('currency'), 'currency');
            result.orderDate = parseDate(root.get('date'));
            result.customerEmail = parseCustomerEmail(root.get('customer'));
            result.lines = new List<Line>();
            result.total = 0;

            Object linesObj = root.get('lines');
            if (linesObj != null) {
                if (!(linesObj instanceof List<Object>)) {
                    throw new PayloadException('lines must be a JSON array.');
                }
                List<Object> rawLines = (List<Object>) linesObj;
                Decimal total = 0;
                for (Object rawLine : rawLines) {
                    Line line = parseLine(rawLine);
                    result.lines.add(line);
                    total += line.lineTotal;
                }
                result.total = total;
            }

            return result;
        } catch (PayloadException e) {
            throw e;
        } catch (Exception e) {
            throw new PayloadException(e.getMessage());
        }
    }

    public static String toAcknowledgement(Order order) {
        try {
            if (order == null) {
                throw new PayloadException('Order is null.');
            }
            Integer lineCount = (order.lines == null) ? 0 : order.lines.size();
            Decimal total = (order.total == null) ? 0 : order.total;

            JSONGenerator gen = JSON.createGenerator(false);
            gen.writeStartObject();
            if (order.orderNumber == null) {
                gen.writeNullField('number');
            } else {
                gen.writeStringField('number', order.orderNumber);
            }
            gen.writeStringField('status', 'RECEIVED');
            gen.writeNumberField('lineCount', lineCount);
            gen.writeNumberField('total', total);
            gen.writeEndObject();
            return gen.getAsString();
        } catch (PayloadException e) {
            throw e;
        } catch (Exception e) {
            throw new PayloadException(e.getMessage());
        }
    }

    private static Line parseLine(Object rawLine) {
        if (!(rawLine instanceof Map<String, Object>)) {
            throw new PayloadException('Each line must be a JSON object.');
        }
        Map<String, Object> lineMap = (Map<String, Object>) rawLine;

        String sku = getStringValue(lineMap.get('sku'), 'sku');
        if (String.isBlank(sku)) {
            throw new PayloadException('Missing sku on line.');
        }

        Object quantityObj = lineMap.get('quantity');
        if (quantityObj == null) {
            throw new PayloadException('Missing quantity on line.');
        }
        Integer quantity = toInteger(quantityObj, 'quantity');
        if (quantity == null || quantity <= 0) {
            throw new PayloadException('Quantity must be positive.');
        }

        Object unitPriceObj = lineMap.get('unitPrice');
        if (unitPriceObj == null) {
            throw new PayloadException('Missing unitPrice on line.');
        }
        Decimal unitPrice = toDecimal(unitPriceObj, 'unitPrice');
        if (unitPrice == null || unitPrice < 0) {
            throw new PayloadException('unitPrice must not be negative.');
        }

        Decimal discount = 0;
        Object discountObj = lineMap.get('discount');
        if (discountObj != null) {
            discount = toDecimal(discountObj, 'discount');
            if (discount == null) {
                throw new PayloadException('Invalid discount on line.');
            }
        }

        Line line = new Line();
        line.sku = sku;
        line.quantity = quantity;
        line.unitPrice = unitPrice;
        line.discount = discount;
        line.lineTotal = (Decimal.valueOf(quantity) * unitPrice * (1 - discount))
            .setScale(2, System.RoundingMode.HALF_UP);
        return line;
    }

    private static String parseCustomerEmail(Object customerObj) {
        if (customerObj == null) {
            return null;
        }
        if (!(customerObj instanceof Map<String, Object>)) {
            throw new PayloadException('customer must be a JSON object.');
        }
        Map<String, Object> customerMap = (Map<String, Object>) customerObj;
        return getStringValue(customerMap.get('email'), 'customer.email');
    }

    private static Date parseDate(Object dateObj) {
        if (dateObj == null) {
            return null;
        }
        String dateString = getStringValue(dateObj, 'date');
        if (String.isBlank(dateString)) {
            return null;
        }
        try {
            return Date.valueOf(dateString.trim());
        } catch (Exception e) {
            throw new PayloadException('Invalid date: ' + dateString);
        }
    }

    private static String getStringValue(Object value, String fieldName) {
        if (value == null) {
            return null;
        }
        if (value instanceof String) {
            return (String) value;
        }
        throw new PayloadException('Field ' + fieldName + ' must be a string.');
    }

    private static Decimal toDecimal(Object value, String fieldName) {
        if (value == null) {
            return null;
        }
        if (value instanceof Decimal) {
            return (Decimal) value;
        }
        if (value instanceof Integer) {
            return Decimal.valueOf((Integer) value);
        }
        if (value instanceof Long) {
            return Decimal.valueOf((Long) value);
        }
        if (value instanceof Double) {
            return Decimal.valueOf((Double) value);
        }
        throw new PayloadException('Field ' + fieldName + ' must be a number.');
    }

    private static Integer toInteger(Object value, String fieldName) {
        if (value == null) {
            return null;
        }
        if (value instanceof Integer) {
            return (Integer) value;
        }
        if (value instanceof Long) {
            Long longValue = (Long) value;
            if (longValue > 2147483647L || longValue < -2147483648L) {
                throw new PayloadException('Field ' + fieldName + ' is out of range.');
            }
            return Integer.valueOf(String.valueOf(longValue));
        }
        Decimal decimalValue = toDecimal(value, fieldName);
        if (decimalValue == null) {
            return null;
        }
        if (decimalValue.setScale(0, System.RoundingMode.DOWN) != decimalValue.setScale(0)) {
            // Allow integral decimals such as 2.0, reject fractional quantities.
            if (decimalValue != decimalValue.setScale(0)) {
                throw new PayloadException('Field ' + fieldName + ' must be an integer.');
            }
        }
        try {
            return decimalValue.intValue();
        } catch (Exception e) {
            throw new PayloadException('Field ' + fieldName + ' is out of range.');
        }
    }
}
