        CapturingMock(Integer statusCode, String body) {
            this.statusCode = statusCode;
            this.body = body;
        }

        public HttpResponse respond(HttpRequest req) {
            AddressVerificationServiceTest.calloutCount++;
            AddressVerificationServiceTest.capturedRequest = req;
            HttpResponse res = new HttpResponse();
            res.setStatusCode(this.statusCode);
            res.setHeader('Content-Type', 'application/json');
            if (this.body != null) {
                res.setBody(this.body);
            }
            return res;
        }
    }

    private static void installMock(Integer statusCode, String body) {
        capturedRequest = null;
        calloutCount = 0;
        Test.setMock(HttpCalloutMock.class, new CapturingMock(statusCode, body));
    }

