    private static final Date EXPECTED_DUE = Date.newInstance(2030, 1, 22); // CLOSE_DATE + 7

    // ---------- Helpers ----------

    private static Account makeAccount(String rating) {
        Account a = new Account(Name = 'Test Account ' + Math.abs(Crypto.getRandomInteger()));
        if (rating != null) {
            a.Rating = rating;
        }
        insert a;
        return a;
    }

    private static Opportunity makeOpp(Id accountId, String stage) {
        return new Opportunity(
            Name = 'Test Opp ' + Math.abs(Crypto.getRandomInteger()),
            AccountId = accountId,
            StageName = stage,
            CloseDate = CLOSE_DATE
        );
    }

    private static Opportunity queryOpp(Id oppId) {
        return [SELECT Id, Name, StageName, NextStep, CloseDate, AccountId, OwnerId
                FROM Opportunity WHERE Id = :oppId];
    }

    private static List<Task> tasksFor(Set<Id> oppIds) {
        return [SELECT Id, Subject, WhatId, OwnerId, ActivityDate, Priority
                FROM Task WHERE WhatId IN :oppIds];
    }

    private static List<Task> tasksFor(Id oppId) {
        return tasksFor(new Set<Id>{ oppId });
    }

    private static String ratingOf(Id accountId) {
        return [SELECT Rating FROM Account WHERE Id = :accountId].Rating;
    }

    private static User createOtherUser() {
        User other;
