public class PicklistService {

    public class Option {
        public String value;
        public String label;
        public Boolean isDefault;

        public Option() {
            this.isDefault = false;
        }

        public Option(String value, String label, Boolean isDefault) {
            this.value = value;
            this.label = label;
            this.isDefault = isDefault == true;
        }
    }

    public class PicklistServiceException extends Exception {
    }

    public static List<PicklistService.Option> activeOptions(String objectApiName, String fieldApiName) {
        try {
            if (String.isBlank(objectApiName)) {
                throw new PicklistServiceException('Object API name must not be null or blank.');
            }
            if (String.isBlank(fieldApiName)) {
                throw new PicklistServiceException('Field API name must not be null or blank.');
            }

            String objectName = objectApiName.trim();
            String fieldName = fieldApiName.trim();

            Map<String, Schema.SObjectType> globalDescribe = Schema.getGlobalDescribe();

            Schema.SObjectType sObjectType = null;
            for (String key : globalDescribe.keySet()) {
                if (key != null && key.equalsIgnoreCase(objectName)) {
                    sObjectType = globalDescribe.get(key);
                    break;
                }
            }

            if (sObjectType == null) {
                throw new PicklistServiceException('Object does not exist: ' + objectApiName);
            }

            Schema.DescribeSObjectResult objectDescribe = sObjectType.getDescribe();
            Map<String, Schema.SObjectField> fieldMap = objectDescribe.fields.getMap();

            Schema.SObjectField sObjectField = null;
            for (String key : fieldMap.keySet()) {
                if (key != null && key.equalsIgnoreCase(fieldName)) {
                    sObjectField = fieldMap.get(key);
                    break;
                }
            }

            if (sObjectField == null) {
                throw new PicklistServiceException(
                    'Field does not exist on object ' + objectApiName + ': ' + fieldApiName
                );
            }

            Schema.DescribeFieldResult fieldDescribe = sObjectField.getDescribe();
            Schema.DisplayType fieldType = fieldDescribe.getType();

            if (fieldType != Schema.DisplayType.Picklist && fieldType != Schema.DisplayType.MultiPicklist) {
                throw new PicklistServiceException(
                    'Field is not a picklist or multi-select picklist: ' + objectApiName + '.' + fieldApiName
                );
            }

            List<PicklistService.Option> result = new List<PicklistService.Option>();

            for (Schema.PicklistEntry entry : fieldDescribe.getPicklistValues()) {
                if (entry != null && entry.isActive()) {
                    Option opt = new Option();
                    opt.value = entry.getValue();
                    opt.label = entry.getLabel();
                    opt.isDefault = entry.isDefaultValue() == true;
                    result.add(opt);
                }
            }

            return result;
        } catch (PicklistServiceException e) {
            throw e;
        } catch (Exception e) {
            throw new PicklistServiceException(
                'Unable to retrieve picklist options for ' + objectApiName + '.' + fieldApiName + ': ' + e.getMessage()
            );
        }
    }
}
