public with sharing class ShipmentEventHandler {

    public static void handle(List<FB_Shipment_Event__e> events) {
        if (events == null || events.isEmpty()) {
            return;
        }

        // Last event for an order wins. Order_Number__c on the order is
        // always upper case, so normalise event values for matching.
        Map<String, FB_Shipment_Event__e> eventByOrderNumber = new Map<String, FB_Shipment_Event__e>();

        for (FB_Shipment_Event__e event : events) {
            if (event == null || String.isBlank(event.Order_Number__c)) {
                continue;
            }
            String orderNumber = event.Order_Number__c.trim().toUpperCase();
            eventByOrderNumber.put(orderNumber, event);
        }

        if (eventByOrderNumber.isEmpty()) {
            return;
        }

        // Single SOQL query for all events in this call.
        List<FB_Sales_Order__c> orders = [
            SELECT Id, Order_Number__c, Status__c, Tracking_Number__c, Carrier__c, Shipped_Date__c
            FROM FB_Sales_Order__c
            WHERE Order_Number__c IN :eventByOrderNumber.keySet()
        ];

        List<FB_Sales_Order__c> ordersToUpdate = new List<FB_Sales_Order__c>();
        Date today = Date.today();

        for (FB_Sales_Order__c orderRecord : orders) {
            if (orderRecord.Status__c == 'Cancelled') {
                continue;
            }
            // Orders store Order_Number__c in upper case; normalise defensively.
            String orderNumber = orderRecord.Order_Number__c == null
                ? null
                : orderRecord.Order_Number__c.trim().toUpperCase();
            FB_Shipment_Event__e event = eventByOrderNumber.get(orderNumber);
            if (event == null) {
                continue;
            }
            ordersToUpdate.add(new FB_Sales_Order__c(
                Id = orderRecord.Id,
                Status__c = 'Shipped',
                Tracking_Number__c = event.Tracking_Number__c,
                Carrier__c = event.Carrier__c,
                Shipped_Date__c = today
            ));
        }

        // Single DML statement for all events in this call.
        if (!ordersToUpdate.isEmpty()) {
            update ordersToUpdate;
        }
    }
}
