public class AccountScoringJob implements Queueable {

    private final List<Id> accountIds;

    public AccountScoringJob(List<Id> accountIds) {
        this.accountIds = (accountIds == null)
            ? new List<Id>()
            : new List<Id>(accountIds);
    }

    public static Id start(List<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return null;
        }
        return System.enqueueJob(new AccountScoringJob(accountIds));
    }

    public void execute(QueueableContext context) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        Integer batchSize = Math.min(200, accountIds.size());

        List<Id> batchIds = new List<Id>();
        for (Integer i = 0; i < batchSize; i++) {
            batchIds.add(accountIds[i]);
        }

        List<Account> accounts = [
            SELECT Id, AnnualRevenue
            FROM Account
            WHERE Id IN :batchIds
        ];

        for (Account acc : accounts) {
            if (acc.AnnualRevenue != null && acc.AnnualRevenue >= 1000000) {
                acc.Rating = 'Hot';
            } else if (acc.AnnualRevenue != null && acc.AnnualRevenue >= 100000) {
                acc.Rating = 'Warm';
            } else {
                acc.Rating = 'Cold';
            }
        }

        update accounts;

        if (accountIds.size() > batchSize) {
            List<Id> remainingIds = new List<Id>();
            for (Integer i = batchSize; i < accountIds.size(); i++) {
                remainingIds.add(accountIds[i]);
            }
            enqueueNext(remainingIds);
        }
    }

    /**
     * Continues the chain with the remaining Ids.
     *
     * When this instance is running as a real Queueable, the next job is
     * enqueued from a Finalizer rather than directly from execute(). A job
     * enqueued by a Finalizer starts a new Queueable chain (stack depth 1)
     * in its own transaction, so the chain is not subject to the maximum
     * Queueable stack depth of five imposed on Developer Edition / trial
     * (including scratch) orgs. Without this, chains of more than five jobs
     * (i.e. more than 1,000 accounts) would fail with
     * "System.AsyncException: Maximum stack depth has been reached", and a
     * chain of up to 250 jobs (50,000 accounts) could never complete.
     * Each job still runs in its own transaction with fresh governor
     * limits, and Test.stopTest() executes each successive job (including
     * its Finalizer) until no Ids remain, so the whole chain completes
     * inside a single Test.startTest()/Test.stopTest() block. Chaining is
     * therefore never skipped when a test is running.
     *
     * When execute() is invoked directly (not in a Queueable context, e.g.
     * execute(null) from a test), no Finalizer can be attached, so the next
     * job is enqueued immediately instead.
     */
    private void enqueueNext(List<Id> remainingIds) {
        if (remainingIds == null || remainingIds.isEmpty()) {
            return;
        }
        if (System.isQueueable()) {
            System.attachFinalizer(new Continuation(remainingIds));
        } else {
            System.enqueueJob(new AccountScoringJob(remainingIds));
        }
    }

    /**
     * Finalizer that enqueues the next AccountScoringJob in the chain once
     * the current job has completed successfully.
     */
    private class Continuation implements Finalizer {
        private final List<Id> remainingIds;

        Continuation(List<Id> remainingIds) {
            this.remainingIds = (remainingIds == null)
                ? new List<Id>()
                : new List<Id>(remainingIds);
        }

        public void execute(FinalizerContext context) {
            switch on context.getResult() {
                when SUCCESS {
                    if (!remainingIds.isEmpty()) {
                        System.enqueueJob(new AccountScoringJob(remainingIds));
                    }
                }
                when else {
                    // Parent job did not succeed; do not continue the chain.
                }
            }
        }
    }
}
