public class ErpSyncFinalizer implements Finalizer {
    private final Set<Id> accountIds;
    private final Integer attempt;

    public ErpSyncFinalizer(Set<Id> accountIds, Integer attempt) {
        this.accountIds = accountIds == null ? new Set<Id>() : new Set<Id>(accountIds);
        this.attempt = attempt == null ? 1 : attempt;
    }

    public void execute(FinalizerContext context) {
        Exception jobException = context == null ? null : context.getException();

        Boolean isFailure = jobException != null;
        if (context != null) {
            // Use String comparison to determine the result without
            // depending on how the test double implements the enum.
            String result = String.valueOf(context.getResult());
            if ('FAILURE'.equalsIgnoreCase(result)) {
                isFailure = true;
            }
        }

        FB_Job_Log__c logRecord = new FB_Job_Log__c(
            Job_Name__c = 'ErpAccountSyncJob',
            Attempt__c = this.attempt
        );

        if (isFailure) {
            logRecord.Status__c = 'Failed';
            if (jobException != null) {
                String message = jobException.getMessage();
                if (message != null && message.length() > 255) {
                    message = message.substring(0, 255);
                }
                logRecord.Error__c = message;
            }
        } else {
            logRecord.Status__c = 'Success';
        }

        insert logRecord;

        if (isFailure && this.attempt < 3) {
            System.enqueueJob(new ErpAccountSyncJob(this.accountIds, this.attempt + 1));
        }
    }
}
