/**
 * Keeps Account.FB_Open_Pipeline__c and Account.FB_Open_Opportunities__c
 * in sync with the account's open Opportunities.
 *
 * Runs without sharing so the aggregate always reflects all open
 * Opportunities for the account, regardless of the running user's
 * sharing access.
 *
 * Recursion / re-entrancy strategy:
 * - No static "already ran" flag is used. Several DML statements on the
 *   same Opportunities within one transaction (e.g. a Flow followed by
 *   Apex, or successive statements in a test) must each be recalculated.
 * - Loops with the legacy AccountTrigger are prevented instead by:
 *   1. On update, only recalculating when a field that can affect the
 *      totals changes (Amount, AccountId, StageName / IsClosed). The
 *      AccountTrigger only changes FB_Account_Rating__c, so the
 *      Opportunity update it causes is a no-op here.
 *   2. Only updating an Account when its calculated totals actually
 *      differ from the stored values, avoiding unnecessary Account DML.
 */
public without sharing class OpportunityPipelineHandler {

    public static void handle(
        System.TriggerOperation operation,
        List<Opportunity> newList,
        Map<Id, Opportunity> oldMap
    ) {
        Set<Id> accountIds = new Set<Id>();

        switch on operation {
            when AFTER_INSERT, AFTER_UNDELETE {
                if (newList != null) {
                    for (Opportunity opp : newList) {
                        if (opp.AccountId != null) {
                            accountIds.add(opp.AccountId);
                        }
                    }
                }
            }
            when AFTER_DELETE {
                if (oldMap != null) {
                    for (Opportunity opp : oldMap.values()) {
                        if (opp.AccountId != null) {
                            accountIds.add(opp.AccountId);
                        }
                    }
                }
            }
            when AFTER_UPDATE {
                if (newList != null && oldMap != null) {
                    for (Opportunity opp : newList) {
                        Opportunity oldOpp = oldMap.get(opp.Id);
                        if (oldOpp == null) {
                            if (opp.AccountId != null) {
                                accountIds.add(opp.AccountId);
                            }
                            continue;
                        }
                        if (isRelevantChange(opp, oldOpp)) {
                            // Both the old and the new account can be affected
                            // (e.g. reparenting, closing, reopening).
                            if (opp.AccountId != null) {
                                accountIds.add(opp.AccountId);
                            }
                            if (oldOpp.AccountId != null) {
                                accountIds.add(oldOpp.AccountId);
                            }
                        }
                    }
                }
            }
            when else {
                return;
            }
        }

        accountIds.remove(null);
        if (accountIds.isEmpty()) {
            return;
        }

        recalculate(accountIds);
    }

    private static Boolean isRelevantChange(Opportunity newOpp, Opportunity oldOpp) {
        return newOpp.Amount != oldOpp.Amount
            || newOpp.AccountId != oldOpp.AccountId
            || newOpp.StageName != oldOpp.StageName
            || newOpp.IsClosed != oldOpp.IsClosed;
    }

    private static void recalculate(Set<Id> accountIds) {
        Map<Id, Decimal> pipelineByAccount = new Map<Id, Decimal>();
        Map<Id, Integer> countByAccount = new Map<Id, Integer>();

        // One bulkified aggregate for all affected accounts.
        // SUM ignores null Amounts (blank counts as 0); accounts with no
        // open Opportunities simply have no row and default to 0 / 0 below.
        for (AggregateResult result : [
            SELECT AccountId accountId, SUM(Amount) totalAmount, COUNT(Id) oppCount
            FROM Opportunity
            WHERE AccountId IN :accountIds
              AND IsClosed = false
            GROUP BY AccountId
        ]) {
            Id accountId = (Id) result.get('accountId');
            Decimal totalAmount = (Decimal) result.get('totalAmount');
            Integer oppCount = (Integer) result.get('oppCount');
            pipelineByAccount.put(accountId, totalAmount == null ? 0 : totalAmount);
            countByAccount.put(accountId, oppCount == null ? 0 : oppCount);
        }

        // Fetch current values so Accounts whose totals have not changed
        // are not updated (prevents unnecessary DML and trigger cascades).
        List<Account> accountsToUpdate = new List<Account>();
        for (Account acct : [
            SELECT Id, FB_Open_Pipeline__c, FB_Open_Opportunities__c
            FROM Account
            WHERE Id IN :accountIds
        ]) {
            Decimal newPipeline = pipelineByAccount.containsKey(acct.Id)
                ? pipelineByAccount.get(acct.Id)
                : 0;
            Decimal newCount = countByAccount.containsKey(acct.Id)
                ? countByAccount.get(acct.Id)
                : 0;

            if (acct.FB_Open_Pipeline__c != newPipeline
                || acct.FB_Open_Opportunities__c != newCount) {
                accountsToUpdate.add(new Account(
                    Id = acct.Id,
                    FB_Open_Pipeline__c = newPipeline,
                    FB_Open_Opportunities__c = newCount
                ));
            }
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }
}
