public without sharing class LogPurgeJob implements Schedulable {

    public LogPurgeJob() {
    }

    public void execute(SchedulableContext context) {
        Datetime cutoff30Days = Datetime.now().addDays(-30);
        Datetime cutoff180Days = Datetime.now().addDays(-180);

        // Delete in chunks to stay within DML row limits.
        while (true) {
            List<FB_Integration_Log__c> logsToDelete = [
                SELECT Id
                FROM FB_Integration_Log__c
                WHERE (Level__c = 'ERROR' AND CreatedDate < :cutoff180Days)
                   OR ((Level__c = NULL OR Level__c != 'ERROR') AND CreatedDate < :cutoff30Days)
                LIMIT 9000
            ];

            if (logsToDelete.isEmpty()) {
                break;
            }

            delete logsToDelete;

            if (logsToDelete.size() < 9000) {
                break;
            }
        }
    }

    public static Id scheduleNightly() {
        return System.schedule(
            'Log purge (nightly)',
            '0 0 2 * * ?',
            new LogPurgeJob()
        );
    }
}
