        // Per-opportunity rounding gives 30.09; rounding only the total would give 30.10.
        List<Opportunity> opportunities = new List<Opportunity>{
            makeOpportunity(ACCOUNT_ID_1, 'Prospecting', 100.33, 10),
            makeOpportunity(ACCOUNT_ID_1, 'Prospecting', 100.33, 10),
