        stubSelector(mocks, accountIds, opportunities);

        Test.startTest();
        Map<String, Decimal> result = OpportunityForecastService.weightedAmountByStage(accountIds);
        Test.stopTest();

        Assert.areEqual(2, result.size(), 'Expected one total per distinct stage');
        Assert.areEqual(30.09, result.get('Prospecting'), 'Each opportunity must be rounded to 2 decimals before summing');
        // 199.99 * 33 / 100 = 65.9967 -> 66.00
