            accounts.add(account);
            uow.registerNew(account);

            List<String> contactLastNames = contactLastNamesByAccountName.get(accountName);
            if (contactLastNames == null) {
                continue;
            }

            for (String lastName : contactLastNames) {
                if (String.isBlank(lastName)) {
                    continue;
                }
                Contact contact = new Contact(LastName = lastName);
                uow.registerNew(contact, Contact.AccountId, account);
            }
        }

        uow.commitWork();

        return accounts;
    }
}
