public inherited sharing class OpportunityWinService {
    public static Integer markWon(Set<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return 0;
        }

        List<Opportunity> opportunities = OpportunitiesSelector.newInstance()
            .selectById(opportunityIds);

        if (opportunities == null || opportunities.isEmpty()) {
            return 0;
        }

        fflib_IUnitOfWork unitOfWork = Application.UnitOfWork.newInstance();

        Integer closedCount = 0;

        for (Opportunity opportunity : opportunities) {
            if (opportunity.StageName == 'Closed Won') {
                continue;
            }

            opportunity.StageName = 'Closed Won';
            opportunity.CloseDate = Date.today();

            unitOfWork.registerDirty(opportunity);

            // Publish Immediately events published via registerPublishOnSuccessTransaction
            // (or EventBus.publish directly) would be delivered even if the
            // transaction subsequently fails/rolls back. Publishing after success
            // defers publication until after the transaction commits: fflib
            // enqueues the publication, which only executes if commitWork()
            // completes and the transaction commits. If registerDirty DML in
            // commitWork() fails, the exception propagates before any event
            // is enqueued/published.
            unitOfWork.registerPublishAfterSuccessTransaction(
                new Deal_Won__e(
                    Opportunity_Id__c = String.valueOf(opportunity.Id),
                    Amount__c = opportunity.Amount
                )
            );

            closedCount++;
        }

        // Single commit for all Opportunity updates (and deferred event
        // publication). No try/catch: failures must propagate and no
        // Deal_Won__e may be published for unsaved Opportunities.
        unitOfWork.commitWork();

        return closedCount;
    }
}
