/**
 * Normalizes Contact phone numbers for the dialer.
 *
 * Approach preserved as specified. The only refinements are:
 * - `with sharing` and USER_MODE enforce the caller's sharing, CRUD and
 *   field-level access; otherwise Apex would run in system mode and could
 *   read/update records or fields the user cannot normally access.
 * - Null/empty input (and input containing only null Ids) returns an empty
 *   map without SOQL or DML, and DML is skipped when no contact has a phone.
 *   This avoids wasted governor-limit usage without changing any result.
 * - A defensive fallback message is used if a failed SaveResult somehow
 *   carries no Database.Error, so indexing getErrors()[0] cannot throw.
 */
public with sharing class ContactPhoneCleanup {

    public static Map<Id, String> normalizePhones(List<Id> contactIds) {
        Map<Id, String> failuresByContactId = new Map<Id, String>();

        if (contactIds == null || contactIds.isEmpty()) {
            return failuresByContactId;
        }

        // Deduplicate and drop nulls; SOQL would deduplicate anyway, but a
        // clean bind set keeps the query tidy and bulk-safe.
        Set<Id> uniqueContactIds = new Set<Id>();
        for (Id contactId : contactIds) {
            if (contactId != null) {
                uniqueContactIds.add(contactId);
            }
        }
        if (uniqueContactIds.isEmpty()) {
            return failuresByContactId;
        }

        // Contacts without a phone are excluded by the WHERE clause and are
        // therefore never updated.
        List<Contact> contacts = [
            SELECT Id, Phone
            FROM Contact
            WHERE Id IN :uniqueContactIds
              AND Phone != null
            WITH USER_MODE
        ];

        for (Contact contact : contacts) {
            // Remove every character that is not a digit or '+'.
            // e.g. '+44 (20) 7946-0018' -> '+442079460018'
            String normalized = contact.Phone.replaceAll('[^0-9+]', '');
            // A phone made only of punctuation normalizes to ''; store null
            // instead of a blank string (Salesforce treats them alike, but
            // null is unambiguous).
            contact.Phone = String.isBlank(normalized) ? null : normalized;
        }

        if (contacts.isEmpty()) {
            return failuresByContactId;
        }

        // Single partial-success update: one bad record must not block the rest.
        List<Database.SaveResult> saveResults =
            Database.update(contacts, false, AccessLevel.USER_MODE);

        for (Integer i = 0; i < saveResults.size(); i++) {
            Database.SaveResult result = saveResults[i];
            if (!result.isSuccess()) {
                List<Database.Error> errors = result.getErrors();
                String message = (errors != null && !errors.isEmpty())
                    ? errors[0].getMessage()
                    : 'Unknown error';
                failuresByContactId.put(contacts[i].Id, message);
            }
        }

        return failuresByContactId;
    }
}
