public class PipelineSummary {

    private static final List<String> STAGES = new List<String>{
        'Prospecting',
        'Qualification',
        'Proposal/Price Quote',
        'Negotiation/Review'
    };

    /**
     * Returns total Opportunity Amount per managed open stage for the
     * inclusive CloseDate range.
     *
     * Implementation note — deliberately NOT one query per stage:
     * a single GROUP BY query does the same work in 1 SOQL query instead
     * of 4. Although four hard-coded stages would not, by itself, break
     * the 100-query governor limit today, SOQL in a loop:
     *   - wastes 4x the query / round-trip overhead for identical data,
     *   - counts against the *transaction-wide* limit, so it can push a
     *     caller that already performs its own queries over the limit,
     *   - scales linearly if a fifth stage is ever added, whereas the
     *     grouped query stays at exactly 1 query regardless.
     * One simple, bulk-safe grouped aggregate is therefore preferred.
     */
    public static Map<String, Decimal> totalsByStage(Date fromDate, Date toDate) {
        Map<String, Decimal> totals = new Map<String, Decimal>();
        for (String stage : STAGES) {
            totals.put(stage, 0);
        }

        if (fromDate == null || toDate == null || fromDate > toDate) {
            return totals;
        }

        for (AggregateResult ar : [
            SELECT StageName, SUM(Amount) total
            FROM Opportunity
            WHERE StageName IN :STAGES
              AND CloseDate >= :fromDate
              AND CloseDate <= :toDate
            WITH USER_MODE
            GROUP BY StageName
        ]) {
            String stage = (String) ar.get('StageName');
            Decimal total = (Decimal) ar.get('total');
            // SUM() is null when all matching Amounts are null (rows with
            // no matching opportunities produce no group at all and are
            // already covered by the 0 initialisation above).
            if (stage != null && totals.containsKey(stage)) {
                totals.put(stage, total == null ? 0 : total);
            }
        }

        return totals;
    }
}
