/**
 * Sets Priority to 'High' for Cases whose Account has Rating = 'Hot'.
 *
 * Bulk-safe: collects all AccountIds and issues a single SOQL query
 * regardless of batch size (1 to 200+ records), rather than querying
 * inside the loop, which would hit the 100 SOQL query governor limit.
 */
public with sharing class CasePriorityHandler {

    public static void handleBeforeInsert(List<Case> newCases) {
        Set<Id> accountIds = new Set<Id>();
        for (Case c : newCases) {
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }

        if (accountIds.isEmpty()) {
            return;
        }

        Map<Id, Account> accountsById = new Map<Id, Account>(
            [SELECT Id, Rating FROM Account WHERE Id IN :accountIds]
        );

        for (Case c : newCases) {
            if (c.AccountId == null) {
                continue;
            }
            Account account = accountsById.get(c.AccountId);
            if (account != null && account.Rating == 'Hot') {
                c.Priority = 'High';
            }
        }
    }
}
