/**
 * Pushes newly created Accounts to the ERP as customers.
 *
 * Runs asynchronously via Queueable because callouts cannot be made
 * directly from a trigger, and batches up to 200 customers per request
 * (the ERP payload is a JSON array of 1-200) instead of one callout per
 * account, which would exceed the 100 callouts-per-transaction limit
 * for bulk inserts of up to 200 Accounts. Each customer remains
 * individually traceable in the ERP via its salesforceId.
 */
public class ErpCustomerSync implements Queueable, Database.AllowsCallouts {

    private static final Integer MAX_BATCH_SIZE = 200;
    private static final String ENDPOINT = 'callout:ERP/api/customers';

    private final List<Customer> customers;

    private ErpCustomerSync(List<Customer> customers) {
        this.customers = customers;
    }

    /**
     * Enqueues one Queueable job per chunk of up to 200 Accounts.
     * Called from the Account after-insert trigger.
     */
    public static void enqueueSync(List<Account> accounts) {
        if (accounts == null || accounts.isEmpty()) {
            return;
        }

        List<Customer> chunk = new List<Customer>();
        for (Account acc : accounts) {
            if (acc.Id == null) {
                continue;
            }
            chunk.add(new Customer(acc));
            if (chunk.size() == MAX_BATCH_SIZE) {
                System.enqueueJob(new ErpCustomerSync(chunk));
                chunk = new List<Customer>();
            }
        }
        if (!chunk.isEmpty()) {
            System.enqueueJob(new ErpCustomerSync(chunk));
        }
    }

    public void execute(QueueableContext context) {
        if (customers == null || customers.isEmpty()) {
            return;
        }

        HttpRequest request = new HttpRequest();
        request.setEndpoint(ENDPOINT);
        request.setMethod('POST');
        request.setHeader('Content-Type', 'application/json');
        request.setBody(JSON.serialize(customers));

        // Error handling / retries are out of scope for this ticket;
        // the ERP is expected to answer 202 Accepted.
        new Http().send(request);
    }

    /**
     * Returns the 18-character form of an Id. Ids surfaced in Apex are
     * normally already 18 characters, but this guarantees the contract
     * if a 15-character Id is ever passed in.
     */
    private static String to18CharId(Id recordId) {
        String idString = String.valueOf(recordId);
        if (idString.length() == 18) {
            return idString;
        }
        if (idString.length() != 15) {
            return idString;
        }
        final String suffixChars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ012345';
        String suffix = '';
        for (Integer block = 0; block < 3; block++) {
            Integer flags = 0;
            for (Integer i = 0; i < 5; i++) {
                String c = idString.substring(block * 5 + i, block * 5 + i + 1);
                if (c >= 'A' && c <= 'Z') {
                    flags += (1 << i);
                }
            }
            suffix += suffixChars.substring(flags, flags + 1);
        }
        return idString + suffix;
    }

    @TestVisible
    private class Customer {
        public String salesforceId;
        public String name;
        public String country;

        Customer(Account acc) {
            this.salesforceId = to18CharId(acc.Id);
            this.name = acc.Name;
            this.country = String.isBlank(acc.BillingCountry) ? null : acc.BillingCountry;
        }
    }
}
