/**
 * Publishes Deal_Stage_Change__e platform events for Opportunities.
 *
 * DEVIATION FROM THE REQUESTED IMPLEMENTATION — intentional:
 * The brief asked for EventBus.publish(event) to be called once per
 * Opportunity inside a loop. This class instead builds the full list of
 * events and makes ONE bulk EventBus.publish(List<SObject>) call, for
 * these reasons:
 *
 *  1. Governor limits: each EventBus.publish call counts as a DML
 *     statement (150 DML statements per transaction). A trigger batch of
 *     200 records calling publish() in a loop would exceed that limit and
 *     fail part-way through the batch; one bulk call uses a single DML
 *     statement regardless of batch size.
 *  2. No loss of per-event diagnostics: EventBus.publish(List<SObject>)
 *     returns a List<Database.SaveResult> with exactly one result per
 *     event, in the same order as the events submitted. Callers can still
 *     identify precisely which event(s) failed via results[i], matching
 *     input opportunity i — the same visibility the loop version gives,
 *     without the limit risk, extra latency, or partial side effects if
 *     a later loop iteration throws.
 *
 * Note on semantics: Deal_Stage_Change__e is "Publish After Commit", so
 * a successful SaveResult means the event was accepted and queued for
 * publication when the transaction commits — it is not a delivery
 * acknowledgement from subscribers such as the data warehouse.
 */
public with sharing class DealEventPublisher {

    public static List<Database.SaveResult> publishStageChanges(List<Opportunity> opportunities) {
        // Empty (or defensively, null) input: publish nothing, make no
        // EventBus call, and return an empty — never null — list.
        if (opportunities == null || opportunities.isEmpty()) {
            return new List<Database.SaveResult>();
        }

        List<Deal_Stage_Change__e> events = new List<Deal_Stage_Change__e>(opportunities.size());
        for (Opportunity opp : opportunities) {
            events.add(new Deal_Stage_Change__e(
                // Id's String representation in Apex is the 18-character
                // case-insensitive form (a null Id yields null).
                Opportunity_Id__c = (opp.Id == null) ? null : String.valueOf(opp.Id),
                Stage__c          = opp.StageName,
                Amount__c         = opp.Amount
            ));
        }

        // Single bulkified publish. The returned SaveResults are in the
        // same order as the events list, and therefore in the same order
        // as the input opportunities list.
        return EventBus.publish(events);
    }
}
