/**
 * Maintains Account.Rating from its open Opportunity pipeline:
 *   Hot  - at least one open Opportunity with Amount >= 100,000
 *   Warm - at least one open Opportunity, none that large
 *   Cold - no open Opportunities
 *
 * Runs without sharing because this is a system-derived roll-up: it must
 * be calculated consistently even if the user editing the Opportunity
 * cannot edit the parent Account.
 */
public without sharing class AccountRatingService {

    private static final Decimal HOT_THRESHOLD = 100000;

    /**
     * Asynchronous entry point. A Set<Id> is used so a whole trigger
     * batch is handled by one future invocation with one aggregate
     * query and one DML statement, regardless of batch size.
     */
    @future
    public static void recalculate(Set<Id> accountIds) {
        recalculateNow(accountIds);
    }

    /**
     * Synchronous implementation, shared by the future method and by
     * callers (e.g. triggers firing inside batch/future contexts) that
     * are not permitted to make a future call.
     */
    public static void recalculateNow(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        Set<Id> validAccountIds = new Set<Id>();
        for (Id accountId : accountIds) {
            if (accountId != null) {
                validAccountIds.add(accountId);
            }
        }
        if (validAccountIds.isEmpty()) {
            return;
        }

        // One aggregate query for all accounts: largest open Amount
        // per account. Accounts absent from the result have no open
        // Opportunities. MAX ignores null Amounts, which correctly
        // leaves such accounts Warm rather than Hot.
        Map<Id, Decimal> maxOpenAmountByAccount = new Map<Id, Decimal>();
        for (AggregateResult result : [
            SELECT AccountId, MAX(Amount) maxAmount
            FROM Opportunity
            WHERE AccountId IN :validAccountIds
              AND IsClosed = false
            GROUP BY AccountId
        ]) {
            maxOpenAmountByAccount.put(
                (Id) result.get('AccountId'),
                (Decimal) result.get('maxAmount')
            );
        }

        List<Account> accountsToUpdate = new List<Account>();
        for (Account acct : [
            SELECT Id, Rating
            FROM Account
            WHERE Id IN :validAccountIds
        ]) {
            String newRating;
            if (!maxOpenAmountByAccount.containsKey(acct.Id)) {
                newRating = 'Cold';
            } else {
                Decimal maxAmount = maxOpenAmountByAccount.get(acct.Id);
                newRating = (maxAmount != null && maxAmount >= HOT_THRESHOLD)
                    ? 'Hot'
                    : 'Warm';
            }

            // Avoid unnecessary DML, workflow/trigger churn and
            // LastModifiedDate changes when nothing actually changed.
            if (acct.Rating != newRating) {
                accountsToUpdate.add(new Account(
                    Id = acct.Id,
                    Rating = newRating
                ));
            }
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }
}
