/**
 * Applies standard product discounts to new OpportunityLineItems.
 *
 * Change from the requested approach, and why:
 * PricingRules.standardDiscountFor(Id) performs a SOQL query on every call.
 * Calling it once per line would issue up to 200 queries for a 200-line CPQ
 * quote, exceeding the 100-query synchronous SOQL governor limit.
 *
 * Instead, this handler queries Product2 once in bulk and then calls
 * PricingRules.standardDiscountForFamily(String) for each line. The
 * family-to-discount rules therefore remain solely in PricingRules and are
 * not copied into this class, while the trigger stays bulk-safe.
 */
public with sharing class LineItemDiscountHandler {

    public static void applyStandardDiscounts(List<OpportunityLineItem> lines) {
        if (lines == null || lines.isEmpty()) {
            return;
        }

        Set<Id> productIds = new Set<Id>();
        for (OpportunityLineItem line : lines) {
            // Preserve any explicitly supplied discount, including 0.
            if (line.Discount == null && line.Product2Id != null) {
                productIds.add(line.Product2Id);
            }
        }

        if (productIds.isEmpty()) {
            return;
        }

        Map<Id, Product2> productsById = new Map<Id, Product2>([
            SELECT Id, Family
            FROM Product2
            WHERE Id IN :productIds
        ]);

        for (OpportunityLineItem line : lines) {
            if (line.Discount == null && line.Product2Id != null) {
                Product2 product = productsById.get(line.Product2Id);
                String family = product == null ? null : product.Family;
                line.Discount = PricingRules.standardDiscountForFamily(family);
            }
        }
    }
}
