trigger CaseTrigger on Case (after update) {
    Set<Id> newlyClosedCaseIds = new Set<Id>();

    for (Case newCase : Trigger.new) {
        Case oldCase = Trigger.oldMap.get(newCase.Id);

        if (oldCase != null
            && !oldCase.IsClosed
            && newCase.IsClosed
            && newCase.ContactId != null) {
            newlyClosedCaseIds.add(newCase.Id);
        }
    }

    if (!newlyClosedCaseIds.isEmpty()) {
        // One Queueable per transaction, not per case: per-case enqueues
        // would exceed the 50-Queueable-per-transaction governor limit
        // on bulk closes (up to 200 cases via the API / list views).
        System.enqueueJob(new CaseSurveyJob(newlyClosedCaseIds));
    }
}
