```apex
public with sharing class CaseSurveyJob implements Queueable {

    private final Set<Id> caseIds;

    public CaseSurveyJob(Set<Id> caseIds) {
        // Defensive copy so callers cannot mutate the job's state after enqueueing.
        this.caseIds = (caseIds == null) ? new Set<Id>() : new Set<Id>(caseIds);
    }

    /** Convenience constructor for handling a single case. */
    public CaseSurveyJob(Id caseId) {
        this(caseId == null ? new Set<Id>() : new Set<Id>{ caseId });
    }

    public void execute(QueueableContext context) {
        if (caseIds.isEmpty()) {
            return;
        }

        List<Task> surveyTasks = new List<Task>();

        // Re-query at execution time: CaseNumber is not carried by an Id-only
        // payload, and IsClosed/ContactId may have changed since the trigger ran.
        // USER_MODE enforces the running user's object/field access.
        for (Case c : [
            SELECT Id, CaseNumber, ContactId
            FROM Case
            WHERE Id IN :caseIds
              AND IsClosed = true
              AND ContactId != null
            WITH USER_MODE
        ]) {
            surveyTasks.add(new Task(
                WhatId       = c.Id,
                WhoId        = c.ContactId,
                Subject      = 'CSAT survey: ' + c.CaseNumber,
                ActivityDate = Date.today().addDays(2),
                Status       = 'Not Started'
            ));
        }

        if (!surveyTasks.isEmpty()) {
            // allOrNone = false preserves the per-case isolation the original
            // one-job-per-case design aimed for: a single failing Task does
            // not roll back the survey Tasks for the other cases.
            Database.insert(surveyTasks, false, AccessLevel.USER_MODE);
        }
    }
}
