/**
 * Sends renewal reminder emails to Opportunity owners.
 *
 * Why the requested one-call-per-Opportunity loop was changed:
 * Apex allows only 10 Messaging.sendEmail invocations per transaction.
 * Calling sendEmail inside a loop for up to 200 Opportunities would throw
 * System.LimitException on the 11th iteration, so most reminders would
 * never be attempted.
 *
 * Building all Messaging.SingleEmailMessage objects first and making a
 * single bulk Messaging.sendEmail(messages, false) call avoids that limit.
 * The false allOrNothing argument provides the intended partial-success
 * behaviour: a failure for one message does not prevent the others from
 * being sent, and SendEmailResult allows successful sends to be counted.
 */
public with sharing class RenewalReminderService {

    public static Integer sendReminders(List<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return 0;
        }

        Set<Id> uniqueOpportunityIds = new Set<Id>();
        for (Id opportunityId : opportunityIds) {
            if (opportunityId != null) {
                uniqueOpportunityIds.add(opportunityId);
            }
        }

        if (uniqueOpportunityIds.isEmpty()) {
            return 0;
        }

        List<Opportunity> opportunities = [
            SELECT Id, Name, CloseDate, OwnerId
            FROM Opportunity
            WHERE Id IN :uniqueOpportunityIds
        ];

        if (opportunities.isEmpty()) {
            return 0;
        }

        List<Messaging.SingleEmailMessage> messages =
            new List<Messaging.SingleEmailMessage>();

        for (Opportunity opp : opportunities) {
            if (opp.OwnerId == null) {
                continue;
            }

            String closeDateText = opp.CloseDate != null
                ? String.valueOf(opp.CloseDate)
                : 'not set';

            Messaging.SingleEmailMessage message =
                new Messaging.SingleEmailMessage();
            message.setTargetObjectId(opp.OwnerId);
            message.setSaveAsActivity(false);
            message.setSubject('Renewal due: ' + opp.Name);
            message.setPlainTextBody(
                'Hello,\n\n' +
                'The renewal for opportunity "' + opp.Name +
                '" is due.\n' +
                'Close date: ' + closeDateText + '.\n\n' +
                'Please review the opportunity and take the necessary action.'
            );

            messages.add(message);
        }

        if (messages.isEmpty()) {
            return 0;
        }

        Integer sentCount = 0;
        List<Messaging.SendEmailResult> results =
            Messaging.sendEmail(messages, false);

        for (Messaging.SendEmailResult result : results) {
            if (result.isSuccess()) {
                sentCount++;
            }
        }

        return sentCount;
    }
}
```

**Why I changed your approach:** `[SELECT ... FROM Contact]` with no filter would attempt to return all ~2.3M contacts, exceeding the 50,000 query-row governor limit (and likely heap/CPU limits) and throwing a `LimitException` on every account update — it is not bulk-safe at any batch size. The fix below keeps your "one query, no queries in loops" goal, but makes that single query *selective*: it filters by `AccountId IN :changedAccountIds` (an indexed field), so it only ever returns contacts belonging to accounts whose `BillingCountry` actually changed in this transaction.

