```apex
/**
 * When an Account's headquarters (BillingCountry) moves, its Contacts follow —
 * but only Contacts that have not deliberately diverged: those whose
 * MailingCountry is blank or still matches the Account's previous BillingCountry.
 * Contacts with any other MailingCountry, and Contacts of Accounts whose
 * BillingCountry did not change, are left untouched.
 */
public with sharing class AccountCountrySync {

    public static void handleAfterUpdate(Map<Id, Account> oldMap, Map<Id, Account> newMap) {
        if (oldMap == null || newMap == null || newMap.isEmpty()) {
            return;
        }

        // 1. Identify only the Accounts whose BillingCountry actually changed.
        Set<Id> changedAccountIds = new Set<Id>();
        for (Id accountId : newMap.keySet()) {
            Account oldAccount = oldMap.get(accountId);
            Account newAccount = newMap.get(accountId);
            if (oldAccount == null) {
                continue;
            }
            if (oldAccount.BillingCountry != newAccount.BillingCountry) {
                changedAccountIds.add(accountId);
            }
        }

        if (changedAccountIds.isEmpty()) {
            return;
        }

        // 2. One selective query (outside any loop): Contacts of the changed
        //    Accounts only. Filtering on the indexed AccountId lookup keeps
        //    this well within governor limits regardless of org size.
        List<Contact> candidateContacts = [
            SELECT Id, AccountId, MailingCountry
            FROM Contact
            WHERE AccountId IN :changedAccountIds
        ];

        // 3. In-memory filtering: sync only blank or previously-matching Contacts.
        List<Contact> contactsToUpdate = new List<Contact>();
        for (Contact con : candidateContacts) {
            String previousBillingCountry = oldMap.get(con.AccountId).BillingCountry;
            String newBillingCountry = newMap.get(con.AccountId).BillingCountry;

            Boolean followsAccount = String.isBlank(con.MailingCountry)
                || con.MailingCountry == previousBillingCountry;

            if (followsAccount && con.MailingCountry != newBillingCountry) {
                con.MailingCountry = newBillingCountry;
                contactsToUpdate.add(con);
            }
        }

        // 4. One bulk DML statement (outside any loop), only when needed.
        if (!contactsToUpdate.isEmpty()) {
            update contactsToUpdate;
        }
    }
}
