import { LightningElement, api } from 'lwc';

export default class AccountContactList extends LightningElement {
    @api contacts;

    get hasContacts() {
        return Array.isArray(this.contacts) && this.contacts.length > 0;
    }

    get sortedContacts() {
        if (!this.hasContacts) {
            return [];
        }
        // Copy the parent-owned array before sorting so it is never mutated,
        // and copy each item before adding the derived hasTitle flag.
        return [...this.contacts]
            .sort((a, b) =>
                String(a?.Name ?? '').localeCompare(String(b?.Name ?? ''))
            )
            .map((contact) => ({
                ...contact,
                hasTitle: Boolean(contact?.Title)
            }));
    }

    get contactCountLabel() {
        const count = this.hasContacts ? this.contacts.length : 0;
        return count === 1 ? '1 contact' : `${count} contacts`;
    }
}
