import { LightningElement } from 'lwc';
import searchContacts from '@salesforce/apex/ContactController.searchContacts';

export default class ContactSearch extends LightningElement {
    contacts = [];
    errorMessage;

    _debounceTimer;
    _requestCounter = 0;

    handleChange(event) {
        let rawValue = '';

        if (event?.detail && typeof event.detail.value === 'string') {
            rawValue = event.detail.value;
        } else if (event?.target && typeof event.target.value === 'string') {
            rawValue = event.target.value;
        } else if (
            event?.currentTarget &&
            typeof event.currentTarget.value === 'string'
        ) {
            rawValue = event.currentTarget.value;
        }

        const searchTerm = rawValue.trim();

        if (this._debounceTimer) {
            clearTimeout(this._debounceTimer);
            this._debounceTimer = undefined;
        }

        if (searchTerm.length < 2) {
            // Invalidate any in-flight request so its late response
            // cannot repopulate the cleared results.
            this._requestCounter += 1;
            this.contacts = [];
            this.errorMessage = undefined;
            return;
        }

        this._debounceTimer = setTimeout(() => {
            this._debounceTimer = undefined;

            const requestId = ++this._requestCounter;

            searchContacts({ searchTerm })
                .then((result) => {
                    // Ignore responses to older, superseded requests.
                    if (requestId !== this._requestCounter) {
                        return;
                    }
                    this.contacts = result ?? [];
                    this.errorMessage = undefined;
                })
                .catch((error) => {
                    // Ignore failures from older, superseded requests.
                    if (requestId !== this._requestCounter) {
                        return;
                    }
                    this.contacts = [];
                    this.errorMessage =
                        error?.body?.message ??
                        error?.message ??
                        'An unexpected error occurred.';
                });
        }, 300);
    }

    disconnectedCallback() {
        if (this._debounceTimer) {
            clearTimeout(this._debounceTimer);
            this._debounceTimer = undefined;
        }
        // Prevent an in-flight response from updating a removed component.
        this._requestCounter += 1;
    }
}
