import { LightningElement, api } from 'lwc';

export default class OrderLinesPanel extends LightningElement {
    @api lines = [];

    showError = false;

    handleReset() {
        const editors = this.template.querySelectorAll('c-line-item-editor');
        editors.forEach((editor) => {
            editor.reset();
        });
    }

    handleSubmit() {
        const editors = Array.from(
            this.template.querySelectorAll('c-line-item-editor')
        );

        // Validate every editor, without short-circuiting, so all
        // invalid lines show their errors at once.
        const results = editors.map((editor) => editor.validate());
        const allValid = results.every((result) => result === true);

        if (allValid) {
            this.showError = false;
            const lines = editors.map((editor) => editor.getValue());
            this.dispatchEvent(
                new CustomEvent('submit', {
                    detail: { lines },
                    bubbles: true,
                    composed: true
                })
            );
        } else {
            this.showError = true;
        }
    }
}
