import { LightningElement } from 'lwc';
import getQueueStats from '@salesforce/apex/QueueController.getQueueStats';

const REFRESH_INTERVAL_MS = 60000;

export default class QueueMonitor extends LightningElement {
    waiting;
    longestWaitMinutes;
    error;

    _hasLoaded = false;
    _intervalId = null;
    _isLoading = false;

    get hasStats() {
        return this._hasLoaded;
    }

    get errorMessage() {
        return this.error?.body?.message;
    }

    handleVisibilityChange = () => {
        if (document.visibilityState === 'hidden') {
            this.stopPolling();
        } else if (document.visibilityState === 'visible') {
            this.loadStats();
            this.stopPolling();
            this.startPolling();
        }
    };

    connectedCallback() {
        document.addEventListener(
            'visibilitychange',
            this.handleVisibilityChange
        );

        if (document.visibilityState !== 'hidden') {
            this.loadStats();
            this.startPolling();
        }
    }

    disconnectedCallback() {
        this.stopPolling();
        document.removeEventListener(
            'visibilitychange',
            this.handleVisibilityChange
        );
    }

    startPolling() {
        if (this._intervalId !== null) {
            return;
        }
        this._intervalId = setInterval(() => {
            this.loadStats();
        }, REFRESH_INTERVAL_MS);
    }

    stopPolling() {
        if (this._intervalId !== null) {
            clearInterval(this._intervalId);
            this._intervalId = null;
        }
    }

    async loadStats() {
        if (this._isLoading) {
            return;
        }
        if (document.visibilityState === 'hidden') {
            return;
        }

        this._isLoading = true;
        try {
            const result = await getQueueStats();
            this.waiting = result.waiting;
            this.longestWaitMinutes = result.longestWaitMinutes;
            this._hasLoaded = true;
            this.error = undefined;
        } catch (error) {
            this.error = error;
        } finally {
            this._isLoading = false;
        }
    }
}
