import { LightningElement, api } from 'lwc';

let instanceCounter = 0;

export default class StatusListbox extends LightningElement {
    @api label;

    _options = [];
    _value = '';
    _activeValue = null;
    _uid = `status-listbox-${++instanceCounter}`;

    @api
    get options() {
        return this._options;
    }

    set options(value) {
        this._options = Array.isArray(value) ? value : [];
        if (
            this._activeValue === null ||
            !this._options.some((option) => option.value === this._activeValue)
        ) {
            this._syncActiveFromValue();
        }
    }

    @api
    get value() {
        return this._value;
    }

    set value(value) {
        const newValue = value ?? '';
        const changed = newValue !== this._value;
        this._value = newValue;
        if (changed || this._activeValue === null) {
            this._syncActiveFromValue();
        }
    }

    _syncActiveFromValue() {
        if (
            this._value &&
            this._options.some((option) => option.value === this._value)
        ) {
            this._activeValue = this._value;
        } else if (this._options.length > 0) {
            this._activeValue = this._options[0].value;
        } else {
            this._activeValue = null;
        }
    }

    get renderedOptions() {
        return this._options.map((option, index) => ({
            id: `${this._uid}-option-${index}`,
            value: option.value,
            label: option.label,
            ariaSelected: option.value === this._value ? 'true' : 'false'
        }));
    }

    get activeId() {
        const index = this._options.findIndex(
            (option) => option.value === this._activeValue
        );
        return index >= 0 ? `${this._uid}-option-${index}` : '';
    }

    handleKeyDown(event) {
        const key = event.key;
        const handledKeys = ['ArrowDown', 'ArrowUp', 'Home', 'End', 'Enter', ' '];

        if (!handledKeys.includes(key)) {
            return;
        }

        event.preventDefault();

        if (this._options.length === 0) {
            return;
        }

        let activeIndex = this._options.findIndex(
            (option) => option.value === this._activeValue
        );
        if (activeIndex < 0) {
            activeIndex = 0;
            this._activeValue = this._options[0].value;
        }

        switch (key) {
            case 'ArrowDown':
                activeIndex = Math.min(activeIndex + 1, this._options.length - 1);
                this._activeValue = this._options[activeIndex].value;
                break;
            case 'ArrowUp':
                activeIndex = Math.max(activeIndex - 1, 0);
                this._activeValue = this._options[activeIndex].value;
                break;
            case 'Home':
                this._activeValue = this._options[0].value;
                break;
            case 'End':
                this._activeValue = this._options[this._options.length - 1].value;
                break;
            case 'Enter':
            case ' ':
                this._selectValue(this._activeValue);
                break;
            default:
                break;
        }
    }

    handleClick(event) {
        const value = event.currentTarget.dataset.value;
        this._activeValue = value;
        this._selectValue(value);
    }

    _selectValue(value) {
        this._activeValue = value;
        if (value === this._value) {
            return;
        }
        this._value = value;
        this.dispatchEvent(
            new CustomEvent('change', {
                detail: { value },
                bubbles: true,
                composed: true
            })
        );
    }
}
