/**
 * Sets the current employer for Contacts using NPSP's standard
 * Primary Affiliation mechanism.
 *
 * Updating Contact.npsp__Primary_Affiliation__c causes NPSP's
 * affiliation TDTM handlers to:
 *  - create, or reactivate/promote, a Current and Primary affiliation
 *    to the new Organization;
 *  - change any previous Primary affiliation to Former and non-Primary,
 *    with npe5__EndDate__c set to today; and
 *  - avoid creating a duplicate affiliation where an affiliation to
 *    the same Organization already exists.
 *
 * Contact.AccountId is deliberately not modified, so each Contact
 * remains in its Household Account.
 */
public with sharing class EmployerService {

    public static void setCurrentEmployers(Map<Id, Id> employerByContactId) {
        if (employerByContactId == null || employerByContactId.isEmpty()) {
            return;
        }

        // Ignore incomplete entries rather than clearing a Contact's
        // primary affiliation or attempting to process a null Contact.
        Map<Id, Id> targetEmployerByContactId = new Map<Id, Id>();
        for (Id contactId : employerByContactId.keySet()) {
            Id organizationId = employerByContactId.get(contactId);
            if (contactId != null && organizationId != null) {
                targetEmployerByContactId.put(contactId, organizationId);
            }
        }

        if (targetEmployerByContactId.isEmpty()) {
            return;
        }

        // One SOQL query for all Contacts, regardless of batch size.
        List<Contact> contacts = [
            SELECT Id, npsp__Primary_Affiliation__c
            FROM Contact
            WHERE Id IN :targetEmployerByContactId.keySet()
            WITH SECURITY_ENFORCED
        ];

        List<Contact> contactsToUpdate = new List<Contact>();
        for (Contact contactRecord : contacts) {
            Id targetOrganizationId =
                targetEmployerByContactId.get(contactRecord.Id);

            // No change if the Organization is already the Contact's
            // primary affiliation. This prevents duplicate affiliations
            // and unnecessary NPSP trigger work.
            if (contactRecord.npsp__Primary_Affiliation__c != targetOrganizationId) {
                contactsToUpdate.add(
                    new Contact(
                        Id = contactRecord.Id,
                        npsp__Primary_Affiliation__c = targetOrganizationId
                    )
                );
            }
        }

        // One DML statement for all changed Contacts. Do not create or
        // update npe5__Affiliation__c records directly here: NPSP's
        // standard Primary Affiliation processing maintains the new
        // Current/Primary affiliation and ends the previous Primary
        // affiliation as Former with an end date of today.
        if (!contactsToUpdate.isEmpty()) {
            Database.update(contactsToUpdate, AccessLevel.USER_MODE);
        }
    }
}
