public with sharing class GiftImportService {

    public class WebGift {
        public String firstName;
        public String lastName;
        public String email;        // the donor's personal email
        public Decimal amount;
        public Date giftDate;
    }

    public class ImportResult {
        public Boolean success;
        public Id contactId;        // the matched or created contact
        public Id opportunityId;    // the created donation
        public String errorMessage; // NPSP's failure information when success is false
    }

    private static final String STATUS_IMPORTED = 'Imported';
    private static final String DONOR_CONTACT1 = 'Contact1';

    /**
     * Stages one NPSP Data Import record per gift and processes the staged
     * records synchronously, in the same transaction, through NPSP's
     * BDI (BDI_DataImport_API) engine so that NPSP contact matching,
     * household creation and donation processing rules apply.
     *
     * The staged Data Import records are retained as the audit trail and
     * are the source of the returned results.
     */
    public static List<ImportResult> importGifts(List<WebGift> gifts) {
        List<ImportResult> results = new List<ImportResult>();

        if (gifts == null || gifts.isEmpty()) {
            return results;
        }

        // Pre-size the result list so results can be returned in input order.
        for (Integer i = 0; i < gifts.size(); i++) {
            ImportResult result = new ImportResult();
            result.success = false;
            results.add(result);
        }

        // Stage one NPSP Data Import record per gift.
        List<npsp__DataImport__c> dataImports = new List<npsp__DataImport__c>();
        List<Integer> dataImportGiftIndexes = new List<Integer>();

        for (Integer i = 0; i < gifts.size(); i++) {
            WebGift gift = gifts[i];

            if (gift == null) {
                results[i].success = false;
                results[i].errorMessage = 'Gift is null.';
                continue;
            }

            npsp__DataImport__c dataImport = new npsp__DataImport__c(
                npsp__Contact1_Firstname__c = gift.firstName,
                npsp__Contact1_Lastname__c = gift.lastName,
                npsp__Contact1_Personal_Email__c = gift.email,
                npsp__Donation_Amount__c = gift.amount,
                npsp__Donation_Date__c = gift.giftDate,
                npsp__Donation_Donor__c = DONOR_CONTACT1
            );

            dataImports.add(dataImport);
            dataImportGiftIndexes.add(i);
        }

        if (dataImports.isEmpty()) {
            return results;
        }

        // Insert staged records with partial success so that a record that
        // cannot even be staged does not prevent the others from importing.
        List<npsp__DataImport__c> stagedDataImports = new List<npsp__DataImport__c>();
        List<Integer> stagedGiftIndexes = new List<Integer>();

        Database.SaveResult[] saveResults = Database.insert(dataImports, false);

        for (Integer i = 0; i < saveResults.size(); i++) {
            Integer giftIndex = dataImportGiftIndexes[i];
            Database.SaveResult saveResult = saveResults[i];

            if (saveResult.isSuccess()) {
                stagedDataImports.add(dataImports[i]);
                stagedGiftIndexes.add(giftIndex);
            } else {
                List<String> errors = new List<String>();
                for (Database.Error err : saveResult.getErrors()) {
                    errors.add(err.getMessage());
                }
                results[giftIndex].success = false;
                results[giftIndex].errorMessage = String.join(errors, '; ');
            }
        }

        if (stagedDataImports.isEmpty()) {
            return results;
        }

        // Process synchronously through NPSP's own data import engine using
        // the org's Data Import settings. Do not override those settings:
        // the org defaults match contacts on first name, last name and
        // personal email, and never match existing donations.
        String processingError;

        try {
            npsp__Data_Import_Settings__c dataImportSettings =
                npsp.BDI_DataImport_API.getDataImportSettings();

            npsp.BDI_DataImport_API.processDataImportRecords(
                dataImportSettings,
                stagedDataImports,
                false
            );
        } catch (Exception e) {
            // NPSP normally marks rejected rows as Failed rather than
            // throwing. If processing itself throws, fall through and
            // report whatever NPSP wrote back, supplemented by this error,
            // instead of losing the results for every row.
            processingError = e.getMessage();
        }

        // Re-query the processed staged records: NPSP writes its outcome
        // back to these records, and they remain as the audit trail.
        Set<Id> stagedIds = new Set<Id>();
        for (npsp__DataImport__c dataImport : stagedDataImports) {
            if (dataImport.Id != null) {
                stagedIds.add(dataImport.Id);
            }
        }

        Map<Id, npsp__DataImport__c> processedById =
            new Map<Id, npsp__DataImport__c>();

        if (!stagedIds.isEmpty()) {
            for (npsp__DataImport__c processed : [
                SELECT Id,
                       npsp__Status__c,
                       npsp__Contact1Imported__c,
                       npsp__DonationImported__c,
                       npsp__FailureInformation__c
                FROM npsp__DataImport__c
                WHERE Id IN :stagedIds
                WITH USER_MODE
            ]) {
                processedById.put(processed.Id, processed);
            }
        }

        // Build one result per gift, in input order, from the processed
        // Data Import records.
        for (Integer i = 0; i < stagedDataImports.size(); i++) {
            Integer giftIndex = stagedGiftIndexes[i];
            npsp__DataImport__c staged = stagedDataImports[i];
            npsp__DataImport__c processed = processedById.get(staged.Id);

            // Fall back to the in-memory record if the re-query did not
            // return it for any reason.
            npsp__DataImport__c source = (processed != null) ? processed : staged;

            ImportResult result = results[giftIndex];
            result.contactId = source.npsp__Contact1Imported__c;
            result.opportunityId = source.npsp__DonationImported__c;
            result.success = (source.npsp__Status__c == STATUS_IMPORTED);

            if (result.success) {
                result.errorMessage = null;
            } else if (String.isNotBlank(source.npsp__FailureInformation__c)) {
                result.errorMessage = source.npsp__FailureInformation__c;
            } else if (processingError != null) {
                result.errorMessage = processingError;
            } else if (String.isNotBlank(source.npsp__Status__c)) {
                result.errorMessage = source.npsp__Status__c;
            } else {
                result.errorMessage = 'NPSP Data Import did not import this record.';
            }
        }

        return results;
    }
}
