public with sharing class GauAllocationService {

    public class AllocationException extends Exception {}

    public static List<npsp__Allocation__c> allocateByPercent(
        Id opportunityId,
        Map<Id, Decimal> percentByGauId
    ) {
        // ------------------------------------------------------------------
        // Validate all inputs before changing any data.
        // ------------------------------------------------------------------
        if (opportunityId == null) {
            throw new AllocationException('Opportunity Id is required.');
        }

        if (percentByGauId == null || percentByGauId.isEmpty()) {
            throw new AllocationException('At least one GAU allocation is required.');
        }

        Decimal totalPercent = 0;
        for (Id gauId : percentByGauId.keySet()) {
            if (gauId == null) {
                throw new AllocationException('GAU Id cannot be null.');
            }
            Decimal percent = percentByGauId.get(gauId);
            if (percent == null || percent <= 0) {
                throw new AllocationException(
                    'Allocation percentage for GAU ' + gauId + ' must be greater than 0.'
                );
            }
            totalPercent += percent;
        }

        if (totalPercent > 100) {
            throw new AllocationException(
                'Allocation percentages cannot exceed 100%. Total provided: ' + totalPercent + '%.'
            );
        }

        // Validate the opportunity exists before changing any data.
        List<Opportunity> opportunities = [
            SELECT Id
            FROM Opportunity
            WHERE Id = :opportunityId
            WITH USER_MODE
            LIMIT 1
        ];
        if (opportunities.isEmpty()) {
            throw new AllocationException('Opportunity not found: ' + opportunityId);
        }

        // Validate every GAU exists and is active before changing any data.
        Map<Id, npsp__General_Accounting_Unit__c> gauById =
            new Map<Id, npsp__General_Accounting_Unit__c>([
                SELECT Id, npsp__Active__c
                FROM npsp__General_Accounting_Unit__c
                WHERE Id IN :percentByGauId.keySet()
                WITH USER_MODE
            ]);

        if (gauById.size() != percentByGauId.size()) {
            for (Id gauId : percentByGauId.keySet()) {
                if (!gauById.containsKey(gauId)) {
                    throw new AllocationException('General Accounting Unit not found: ' + gauId);
                }
            }
            throw new AllocationException('One or more General Accounting Units were not found.');
        }

        for (Id gauId : percentByGauId.keySet()) {
            npsp__General_Accounting_Unit__c gau = gauById.get(gauId);
            if (gau.npsp__Active__c != true) {
                throw new AllocationException(
                    'General Accounting Unit is inactive: ' + gauId
                );
            }
        }

        // ------------------------------------------------------------------
        // All validation has passed. Now replace existing allocations.
        // Deletion and insertion occur in the same transaction, so a
        // failure during insertion rolls back the deletion.
        // ------------------------------------------------------------------
        List<npsp__Allocation__c> existingAllocations = [
            SELECT Id
            FROM npsp__Allocation__c
            WHERE npsp__Opportunity__c = :opportunityId
            WITH USER_MODE
        ];
        if (!existingAllocations.isEmpty()) {
            Database.delete(existingAllocations, AccessLevel.USER_MODE);
        }

        List<npsp__Allocation__c> allocationsToInsert = new List<npsp__Allocation__c>();
        for (Id gauId : percentByGauId.keySet()) {
            allocationsToInsert.add(new npsp__Allocation__c(
                npsp__Opportunity__c = opportunityId,
                npsp__General_Accounting_Unit__c = gauId,
                // Percent-based allocation only: do NOT set npsp__Amount__c.
                // NPSP derives Amount from Percent x Opportunity Amount and
                // recalculates it automatically when the Opportunity amount
                // changes, keeping the split correct without further code.
                npsp__Percent__c = percentByGauId.get(gauId)
            ));
        }

        Database.insert(allocationsToInsert, AccessLevel.USER_MODE);

        // Re-query so the returned records reflect any Amount calculated
        // by NPSP automation during insert, preserving insertion order.
        Map<Id, npsp__Allocation__c> insertedById =
            new Map<Id, npsp__Allocation__c>([
                SELECT
                    Id,
                    npsp__Opportunity__c,
                    npsp__General_Accounting_Unit__c,
                    npsp__Amount__c,
                    npsp__Percent__c,
                    npsp__Payment__c,
                    npsp__Campaign__c,
                    npsp__Recurring_Donation__c
                FROM npsp__Allocation__c
                WHERE Id IN :allocationsToInsert
                WITH USER_MODE
            ]);

        List<npsp__Allocation__c> result = new List<npsp__Allocation__c>();
        for (npsp__Allocation__c inserted : allocationsToInsert) {
            npsp__Allocation__c queried = insertedById.get(inserted.Id);
            result.add(queried != null ? queried : inserted);
        }
        return result;
    }
}
