public with sharing class GiftService {

    public static Id recordGift(Id contactId, Decimal amount, Date giftDate) {
        if (amount == null || amount <= 0) {
            throw new IllegalArgumentException('Amount must be greater than zero.');
        }
        if (contactId == null) {
            throw new IllegalArgumentException('Contact does not exist.');
        }

        Date effectiveGiftDate = (giftDate != null) ? giftDate : Date.today();

        List<Contact> donors = [
            SELECT Id, FirstName, LastName, AccountId
            FROM Contact
            WHERE Id = :contactId
            LIMIT 1
        ];
        if (donors.isEmpty()) {
            throw new IllegalArgumentException('Contact does not exist.');
        }
        Contact donor = donors[0];

        if (donor.AccountId == null) {
            throw new IllegalArgumentException('Contact does not have a household account.');
        }

        // All contacts in the same household account.
        List<Contact> householdMembers = [
            SELECT Id
            FROM Contact
            WHERE AccountId = :donor.AccountId
        ];

        // Desired contact roles: exactly one role per contact.
        Map<Id, String> desiredRoleByContactId = new Map<Id, String>();
        for (Contact member : householdMembers) {
            desiredRoleByContactId.put(member.Id, 'Household Member');
        }
        // Donor overrides Household Member for the primary contact.
        desiredRoleByContactId.put(donor.Id, 'Donor');

        String firstName = String.isBlank(donor.FirstName) ? '' : donor.FirstName.trim();
        String lastName = String.isBlank(donor.LastName) ? '' : donor.LastName.trim();
        String donorName = (firstName + ' ' + lastName).trim();
        String dateString = Datetime.newInstance(
            effectiveGiftDate,
            Time.newInstance(0, 0, 0, 0)
        ).format('yyyy-MM-dd');
        String opportunityName = donorName + ' Donation ' + dateString;

        Opportunity opp = new Opportunity(
            Name = opportunityName,
            AccountId = donor.AccountId,
            Amount = amount,
            StageName = 'Closed Won',
            CloseDate = effectiveGiftDate,
            npsp__Primary_Contact__c = donor.Id
        );
        insert opp;

        reconcileContactRoles(opp.Id, donor.Id, desiredRoleByContactId);
        reconcilePayment(opp.Id, amount, effectiveGiftDate);

        return opp.Id;
    }

    private static void reconcileContactRoles(
        Id opportunityId,
        Id donorId,
        Map<Id, String> desiredRoleByContactId
    ) {
        List<OpportunityContactRole> existingRoles = [
            SELECT Id, ContactId, Role, IsPrimary
            FROM OpportunityContactRole
            WHERE OpportunityId = :opportunityId
            ORDER BY CreatedDate ASC
        ];

        Map<Id, OpportunityContactRole> keptByContactId = new Map<Id, OpportunityContactRole>();
        List<OpportunityContactRole> rolesToDelete = new List<OpportunityContactRole>();

        for (OpportunityContactRole ocr : existingRoles) {
            // Delete roles for contacts outside the household and any
            // duplicate role for a contact (NPSP automation may create one).
            if (!desiredRoleByContactId.containsKey(ocr.ContactId)
                || keptByContactId.containsKey(ocr.ContactId)) {
                rolesToDelete.add(ocr);
            } else {
                keptByContactId.put(ocr.ContactId, ocr);
            }
        }

        List<OpportunityContactRole> rolesToUpdate = new List<OpportunityContactRole>();
        List<OpportunityContactRole> rolesToInsert = new List<OpportunityContactRole>();

        for (Id householdContactId : desiredRoleByContactId.keySet()) {
            String desiredRole = desiredRoleByContactId.get(householdContactId);
            Boolean desiredIsPrimary = (householdContactId == donorId);

            if (keptByContactId.containsKey(householdContactId)) {
                OpportunityContactRole kept = keptByContactId.get(householdContactId);
                if (kept.Role != desiredRole || kept.IsPrimary != desiredIsPrimary) {
                    kept.Role = desiredRole;
                    kept.IsPrimary = desiredIsPrimary;
                    rolesToUpdate.add(kept);
                }
            } else {
                rolesToInsert.add(new OpportunityContactRole(
                    OpportunityId = opportunityId,
                    ContactId = householdContactId,
                    Role = desiredRole,
                    IsPrimary = desiredIsPrimary
                ));
            }
        }

        if (!rolesToDelete.isEmpty()) {
            delete rolesToDelete;
        }
        if (!rolesToUpdate.isEmpty()) {
            update rolesToUpdate;
        }
        if (!rolesToInsert.isEmpty()) {
            insert rolesToInsert;
        }
    }

    private static void reconcilePayment(Id opportunityId, Decimal amount, Date giftDate) {
        // NPSP Payments automation normally creates a payment on insert;
        // reuse it if present rather than creating a duplicate.
        List<npe01__OppPayment__c> existingPayments = [
            SELECT Id, npe01__Payment_Amount__c, npe01__Payment_Date__c,
                   npe01__Scheduled_Date__c, npe01__Paid__c
            FROM npe01__OppPayment__c
            WHERE npe01__Opportunity__c = :opportunityId
            ORDER BY CreatedDate ASC
        ];

        if (existingPayments.isEmpty()) {
            insert new npe01__OppPayment__c(
                npe01__Opportunity__c = opportunityId,
                npe01__Payment_Amount__c = amount,
                npe01__Payment_Date__c = giftDate,
                npe01__Scheduled_Date__c = giftDate,
                npe01__Paid__c = true
            );
            return;
        }

        npe01__OppPayment__c kept = existingPayments[0];
        List<npe01__OppPayment__c> paymentsToDelete = new List<npe01__OppPayment__c>();
        for (Integer i = 1; i < existingPayments.size(); i++) {
            paymentsToDelete.add(existingPayments[i]);
        }

        if (!paymentsToDelete.isEmpty()) {
            delete paymentsToDelete;
        }

        if (kept.npe01__Payment_Amount__c != amount
            || kept.npe01__Payment_Date__c != giftDate
            || kept.npe01__Scheduled_Date__c != giftDate
            || kept.npe01__Paid__c != true) {
            kept.npe01__Payment_Amount__c = amount;
            kept.npe01__Payment_Date__c = giftDate;
            kept.npe01__Scheduled_Date__c = giftDate;
            kept.npe01__Paid__c = true;
            update kept;
        }
    }
}
