public with sharing class FamilyService {

    public static void linkParents(Map<Id, Id> parentIdByChildId) {
        if (parentIdByChildId == null || parentIdByChildId.isEmpty()) {
            return;
        }

        // Collect valid, de-duplicated pairs. De-duplicate on the unordered
        // pair so that A->B and B->A in the same call (or the same pair
        // repeated) cannot create duplicates before NPSP's reciprocal
        // processing runs.
        Map<Id, Id> pairsByChildId = new Map<Id, Id>();
        Set<String> seenUnorderedPairs = new Set<String>();
        Set<Id> allContactIds = new Set<Id>();

        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);

            if (childId == null || parentId == null || childId == parentId) {
                continue;
            }

            String forwardKey = String.valueOf(childId) + ':' + String.valueOf(parentId);
            String reverseKey = String.valueOf(parentId) + ':' + String.valueOf(childId);
            if (seenUnorderedPairs.contains(forwardKey) || seenUnorderedPairs.contains(reverseKey)) {
                continue;
            }
            seenUnorderedPairs.add(forwardKey);

            pairsByChildId.put(childId, parentId);
            allContactIds.add(childId);
            allContactIds.add(parentId);
        }

        if (pairsByChildId.isEmpty()) {
            return;
        }

        // Single SOQL query: find any relationship already existing between
        // any of the supplied contacts, in either direction.
        Set<String> existingPairs = new Set<String>();
        for (npe4__Relationship__c existing : [
            SELECT npe4__Contact__c, npe4__RelatedContact__c
            FROM npe4__Relationship__c
            WHERE npe4__Contact__c IN :allContactIds
              AND npe4__RelatedContact__c IN :allContactIds
        ]) {
            if (existing.npe4__Contact__c != null && existing.npe4__RelatedContact__c != null) {
                existingPairs.add(
                    String.valueOf(existing.npe4__Contact__c) + ':' +
                    String.valueOf(existing.npe4__RelatedContact__c)
                );
            }
        }

        List<npe4__Relationship__c> toInsert = new List<npe4__Relationship__c>();

        for (Id childId : pairsByChildId.keySet()) {
            Id parentId = pairsByChildId.get(childId);

            String forwardKey = String.valueOf(childId) + ':' + String.valueOf(parentId);
            String reverseKey = String.valueOf(parentId) + ':' + String.valueOf(childId);

            // Re-run safe: skip if any relationship already links the two
            // contacts in either direction, whatever its type/status.
            if (existingPairs.contains(forwardKey) || existingPairs.contains(reverseKey)) {
                continue;
            }

            // Insert only the child's view: parent is the child's Parent.
            // With NPSP's default "List Setting" reciprocal method, NPSP's
            // own trigger creates exactly one reciprocal record (parent ->
            // child), sets npe4__ReciprocalRelationship__c on both records,
            // copies Status, and resolves the reciprocal Type from the
            // "Parent" Relationship Lookup (Son / Daughter / Child) based on
            // the child's gender. Inserting the reciprocal ourselves would
            // cause NPSP to attempt to create further reciprocals/duplicates.
            toInsert.add(new npe4__Relationship__c(
                npe4__Contact__c = childId,
                npe4__RelatedContact__c = parentId,
                npe4__Type__c = 'Parent',
                npe4__Status__c = 'Current'
            ));
        }

        // Single DML statement of our own; NPSP creates the reciprocals.
        if (!toInsert.isEmpty()) {
            insert toInsert;
        }
    }
}
