```apex
public with sharing class RecordAccessService {

    // UserRecordAccess SOQL queries can evaluate at most 200 RecordIds
    // per query. Batching at 200 keeps 2,000 Ids to 10 SOQL queries,
    // well within the 20-query budget for this method.
    private static final Integer BATCH_SIZE = 200;

    /**
     * Returns the subset of recordIds that the running user can edit,
     * as reported by UserRecordAccess.HasEditAccess. This reflects
     * object permissions, ownership, sharing, role hierarchy,
     * View All / Modify All, and other access mechanisms.
     *
     * @param recordIds Ids to evaluate; may span multiple objects.
     *                    Null or empty input returns an empty set.
     * @return Set of editable Ids; never null.
     */
    public static Set<Id> editableIds(Set<Id> recordIds) {
        Set<Id> editable = new Set<Id>();

        if (recordIds == null || recordIds.isEmpty()) {
            return editable;
        }

        // Copy to a list for batching, ignoring any null entries.
        List<Id> ids = new List<Id>();
        for (Id recordId : recordIds) {
            if (recordId != null) {
                ids.add(recordId);
            }
        }

        if (ids.isEmpty()) {
            return editable;
        }

        Id runningUserId = UserInfo.getUserId();

        for (Integer start = 0; start < ids.size(); start += BATCH_SIZE) {
            Integer endIndex = Math.min(start + BATCH_SIZE, ids.size());
            List<Id> batch = new List<Id>();

            for (Integer i = start; i < endIndex; i++) {
                batch.add(ids.get(i));
            }

            for (UserRecordAccess access : [
                SELECT RecordId
                FROM UserRecordAccess
                WHERE UserId = :runningUserId
                AND RecordId IN :batch
                AND HasEditAccess = true
            ]) {
                editable.add(access.RecordId);
            }
        }

        return editable;
    }
}
