public with sharing class EmployeeDirectoryService {

    public static List<FB_Employee__c> getDirectory() {
        // Object-level check: no read access to the object means no records.
        // Returning an empty list (rather than querying) avoids a
        // QueryException / SecurityException for users without CRUD access.
        if (!Schema.SObjectType.FB_Employee__c.isAccessible()) {
            return new List<FB_Employee__c>();
        }

        // Build the SELECT list dynamically from field-level security.
        // Only fields the running user can read are queried, so inaccessible
        // fields are genuinely absent from the returned SObjects
        // (not present in getPopulatedFieldsAsMap()) rather than null,
        // and the query never throws for users with partial FLS.
        // No user input is used, so there is no SOQL-injection surface.
        List<String> selectableFields = new List<String>{ 'Id', 'Name' };

        if (Schema.SObjectType.FB_Employee__c.fields.Department__c.getDescribe().isAccessible()) {
            selectableFields.add('Department__c');
        }
        if (Schema.SObjectType.FB_Employee__c.fields.Salary__c.getDescribe().isAccessible()) {
            selectableFields.add('Salary__c');
        }
        if (Schema.SObjectType.FB_Employee__c.fields.Personal_Email__c.getDescribe().isAccessible()) {
            selectableFields.add('Personal_Email__c');
        }

        String soql =
            'SELECT ' + String.join(selectableFields, ', ') +
            ' FROM FB_Employee__c' +
            ' ORDER BY Name ASC';

        // Dynamic SOQL executed from a `with sharing` class respects the
        // running user's sharing rules (record-level access). Field/object
        // access has been enforced above by construction of the field list,
        // so WITH SECURITY_ENFORCED / USER_MODE are intentionally not used:
        // they would throw for users lacking access to any selected field.
        return Database.query(soql);
    }
}
