@IsTest
private class TA_Opportunity_GuardAmountDecreaseTest {
    private static Opportunity makeOpportunity(Id opportunityId, Decimal amount) {
        return new Opportunity(Id = opportunityId, Amount = amount);
    }

    private static void assertSingleGuardError(Opportunity opp) {
        Assert.isTrue(
            opp.hasErrors(),
            'Expected the Opportunity to have an error.'
        );
        Assert.areEqual(
            1,
            opp.getErrors().size(),
            'Expected exactly one error on the Opportunity.'
        );
        Assert.areEqual(
            TA_Opportunity_GuardAmountDecrease.ERROR_MESSAGE,
            opp.getErrors()[0].getMessage(),
            'Expected the guard error message.'
        );
    }

    private static void assertNoGuardError(Opportunity opp) {
        Assert.isFalse(
            opp.hasErrors(),
            'Expected the Opportunity to have no errors.'
        );
        Assert.areEqual(
            0,
            opp.getErrors().size(),
            'Expected zero errors on the Opportunity.'
        );
    }

    @IsTest
    static void beforeUpdate_reductionByMoreThanHalf_isRejected() {
        Id opportunityId = TriggerTestUtility.getFakeId(
