public with sharing class TA_Contact_PreventDuplicateEmail implements TriggerAction.BeforeInsert, TriggerAction.BeforeUpdate {
    private static final String ERROR_MESSAGE = 'Another contact on this account already uses this email address.';

    public void beforeInsert(List<SObject> triggerNew) {
        validate(new List<Contact>((List<Contact>) triggerNew), null);
    }

    public void beforeUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        Map<Id, Contact> oldById = new Map<Id, Contact>();
        for (SObject record : triggerOld) {
            Contact oldContact = (Contact) record;
            oldById.put(oldContact.Id, oldContact);
        }
        validate(new List<Contact>((List<Contact>) triggerNew), oldById);
    }

    private void validate(List<Contact> triggerNew, Map<Id, Contact> oldById) {
        List<Contact> candidates = new List<Contact>();
        Set<Id> accountIds = new Set<Id>();
        Set<String> emails = new Set<String>();
        Set<Id> candidateIds = new Set<Id>();

        for (Contact candidate : triggerNew) {
            if (oldById != null) {
                Contact oldContact = oldById.get(candidate.Id);
                if (oldContact != null && candidate.Email == oldContact.Email && candidate.AccountId == oldContact.AccountId) {
                    continue;
                }
            }
            if (candidate.AccountId == null || String.isBlank(candidate.Email)) {
                continue;
            }
            candidates.add(candidate);
            accountIds.add(candidate.AccountId);
            emails.add(candidate.Email.toLowerCase());
            if (candidate.Id != null) {
                candidateIds.add(candidate.Id);
            }
        }

        if (candidates.isEmpty()) {
            return;
        }

        Set<String> existingKeys = new Set<String>();
        // Single bulk query. SOQL string matching is case-insensitive; Apex
        // keys below are also lower-cased for the definitive comparison.
        for (Contact existing : [
            SELECT Id, AccountId, Email
            FROM Contact
            WHERE AccountId IN :accountIds AND Email IN :emails AND Id NOT IN :candidateIds
            WITH USER_MODE
        ]) {
            if (existing.AccountId != null && String.isNotBlank(existing.Email)) {
                existingKeys.add(buildKey(existing.AccountId, existing.Email));
            }
        }

        Set<String> seenKeys = new Set<String>();
        for (Contact candidate : candidates) {
            String key = buildKey(candidate.AccountId, candidate.Email);
            if (existingKeys.contains(key) || seenKeys.contains(key)) {
                candidate.addError(ERROR_MESSAGE);
            } else {
                seenKeys.add(key);
            }
        }
    }

    private String buildKey(Id accountId, String email) {
        return String.valueOf(accountId) + '|' + email.toLowerCase();
    }
}
