public without sharing class TA_Case_RollupOpenCount implements TriggerAction.AfterInsert, TriggerAction.AfterUpdate, TriggerAction.AfterDelete, TriggerAction.AfterUndelete {

    public void afterInsert(List<SObject> triggerNew) {
        Set<Id> accountIds = new Set<Id>();
        for (Case newCase : (List<Case>) triggerNew) {
            if (newCase.AccountId != null) {
                accountIds.add(newCase.AccountId);
            }
        }
        recalculate(accountIds);
    }

    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        Set<Id> accountIds = new Set<Id>();
        List<Case> newCases = (List<Case>) triggerNew;
        List<Case> oldCases = (List<Case>) triggerOld;
        for (Integer i = 0; i < newCases.size(); i++) {
            Case newCase = newCases[i];
            Case oldCase = oldCases[i];
            if (newCase.AccountId != oldCase.AccountId || newCase.IsClosed != oldCase.IsClosed) {
                if (newCase.AccountId != null) {
                    accountIds.add(newCase.AccountId);
                }
                if (oldCase.AccountId != null) {
                    accountIds.add(oldCase.AccountId);
                }
            }
        }
        recalculate(accountIds);
    }

    public void afterDelete(List<SObject> triggerOld) {
        Set<Id> accountIds = new Set<Id>();
        for (Case oldCase : (List<Case>) triggerOld) {
            if (oldCase.AccountId != null) {
                accountIds.add(oldCase.AccountId);
            }
        }
        recalculate(accountIds);
    }

    public void afterUndelete(List<SObject> triggerNew) {
        Set<Id> accountIds = new Set<Id>();
        for (Case newCase : (List<Case>) triggerNew) {
            if (newCase.AccountId != null) {
                accountIds.add(newCase.AccountId);
            }
        }
        recalculate(accountIds);
    }

    private static void recalculate(Set<Id> accountIds) {
        accountIds.remove(null);
        if (accountIds.isEmpty()) {
            return;
        }

        Map<Id, Decimal> openCountByAccountId = new Map<Id, Decimal>();
        for (Id accountId : accountIds) {
            openCountByAccountId.put(accountId, 0);
        }

        for (AggregateResult result : [
            SELECT AccountId accountId, COUNT(Id) openCount
            FROM Case
            WHERE AccountId IN :accountIds AND IsClosed = false
            GROUP BY AccountId
        ]) {
            Id accountId = (Id) result.get('accountId');
            Integer openCount = (Integer) result.get('openCount');
            if (accountId != null) {
                openCountByAccountId.put(accountId, Decimal.valueOf(openCount));
            }
        }

        List<Account> accountsToUpdate = new List<Account>();
        for (Account accountRecord : [
            SELECT Id, FB_Open_Case_Count__c
            FROM Account
            WHERE Id IN :accountIds
        ]) {
            Decimal newCount = openCountByAccountId.get(accountRecord.Id);
            if (accountRecord.FB_Open_Case_Count__c != newCount) {
                accountsToUpdate.add(
                    new Account(
                        Id = accountRecord.Id,
                        FB_Open_Case_Count__c = newCount
                    )
                );
            }
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }
}
