public with sharing class TA_Opportunity_LogAmountChange implements TriggerAction.AfterUpdate {
    /**
     * Amounts for which a task has already been logged in this transaction,
     * keyed by Opportunity Id. The value is the Opportunity.Amount immediately
     * after the change that produced the task.
     *
     * TA_Opportunity_RoundAmount (Order 20, after this action at Order 10)
     * updates the same Opportunities again in the same transaction, changing
     * Amount from that value to its rounded value. That recursive execution
     * is recognised below and does not produce a second task. A later,
     * genuinely different Amount change (whose old Amount is the rounded
     * value, not the value recorded here, or whose new Amount is not merely
     * the rounding of that recorded value) is still logged.
     */
    private static Map<Id, Decimal> loggedAmountByOpportunityId = new Map<Id, Decimal>();

    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        Map<Id, Opportunity> oldById = new Map<Id, Opportunity>();
        for (SObject record : triggerOld) {
            Opportunity oldOpp = (Opportunity) record;
            oldById.put(oldOpp.Id, oldOpp);
        }

        List<Task> tasksToInsert = new List<Task>();

        for (SObject record : triggerNew) {
            Opportunity newOpp = (Opportunity) record;
            Opportunity oldOpp = oldById.get(newOpp.Id);
            if (oldOpp == null) {
                continue;
            }

            if (newOpp.Amount == oldOpp.Amount) {
                continue;
            }

            // Recursive execution caused by TA_Opportunity_RoundAmount in
            // this same transaction: the previous (logged) Amount is now
            // the old Amount, and the new Amount is only its rounded value.
            // This is a consequence of the already-logged change, not a
            // separate change, so suppress the duplicate task but remember
            // the resulting Amount.
            if (
                loggedAmountByOpportunityId.containsKey(newOpp.Id) &&
                loggedAmountByOpportunityId.get(newOpp.Id) == oldOpp.Amount &&
                oldOpp.Amount != null &&
                newOpp.Amount != null &&
                newOpp.Amount ==
                oldOpp.Amount.setScale(0, System.RoundingMode.HALF_UP)
            ) {
                loggedAmountByOpportunityId.put(newOpp.Id, newOpp.Amount);
                continue;
            }

            loggedAmountByOpportunityId.put(newOpp.Id, newOpp.Amount);
            tasksToInsert.add(
                new Task(
                    Subject = 'Amount changed',
                    WhatId = newOpp.Id,
                    Status = 'Completed'
                )
            );
        }

        if (!tasksToInsert.isEmpty()) {
            insert tasksToInsert;
        }
    }
}
